/*
** lu.h -- core declarations for a from-scratch Lua 5.5 compatible interpreter.
**
** This is an original implementation written to match the observable behaviour
** of the reference interpreter.  Layout choices here are deliberately simple:
** everything the runtime needs lives in one header so that the modules can be
** written independently.
*/
#ifndef lu_h
#define lu_h

#include <stddef.h>
#include <stdint.h>
#include <setjmp.h>
#include <stdio.h>

/* ------------------------------------------------------------------ limits */
#define LU_VERSION      "Lua 5.5"
#define LU_RELEASE      "Lua 5.5.1"
#define LU_COPYRIGHT    LU_RELEASE "  Copyright (C) 1994-2026 Lua.org, PUC-Rio"

#define MAXSTACK        1000000   /* max size of the value stack */
#define ERRORSTACKSIZE  (MAXSTACK + 200)
#define MAXCCALLS       200       /* nesting of C calls */
#define MAXUPVAL        255
#define MAXVARS         200
#define MAXREGS         254
#define MAXMETADEPTH    2000      /* __index / __newindex chain limit */
#define BUFSZ           8192

typedef int64_t  lu_Integer;
typedef uint64_t lu_Unsigned;
typedef double   lu_Number;

/* ------------------------------------------------------------------ values */
typedef struct GCObj    GCObj;
typedef struct Str      Str;
typedef struct Table    Table;
typedef struct Proto    Proto;
typedef struct LClosure LClosure;
typedef struct CClosure CClosure;
typedef struct Upval    Upval;
typedef struct Udata    Udata;
typedef struct lua_State lua_State;
typedef struct GlobalState GlobalState;

typedef int (*CFn)(lua_State *L);

/* type tags; the order matters for typename() */
enum {
  T_NIL = 0, T_BOOL, T_NUM, T_STR, T_TAB, T_FUN, T_USER, T_THREAD, T_NTYPES,
  /* refined tags */
  T_INT = 16, T_FLT, T_LCF, T_CCL, T_LCL, T_PROTO, T_UPVAL
};

typedef struct Value {
  union {
    lu_Integer i;
    lu_Number  n;
    GCObj     *gc;
    CFn        f;
    void      *p;
  } u;
  int tt;   /* one of T_NIL,T_BOOL,T_INT,T_FLT,T_LCF,T_STR,T_TAB,T_LCL,T_CCL,
               T_USER,T_THREAD */
} Value;

#define ttisnil(v)      ((v)->tt == T_NIL)
#define ttisbool(v)     ((v)->tt == T_BOOL)
#define ttisint(v)      ((v)->tt == T_INT)
#define ttisflt(v)      ((v)->tt == T_FLT)
#define ttisnum(v)      ((v)->tt == T_INT || (v)->tt == T_FLT)
#define ttisstr(v)      ((v)->tt == T_STR)
#define ttistab(v)      ((v)->tt == T_TAB)
#define ttisuser(v)     ((v)->tt == T_USER)
#define ttisthread(v)   ((v)->tt == T_THREAD)
#define ttisfunc(v)     ((v)->tt == T_LCF || (v)->tt == T_LCL || (v)->tt == T_CCL)
#define ttisgc(v)       ((v)->tt == T_STR || (v)->tt == T_TAB || (v)->tt == T_LCL \
                         || (v)->tt == T_CCL || (v)->tt == T_USER || (v)->tt == T_THREAD)

#define ivalue(v)       ((v)->u.i)
#define fltvalue(v)     ((v)->u.n)
#define nvalue(v)       (ttisint(v) ? (lu_Number)(v)->u.i : (v)->u.n)
#define bvalue(v)       ((int)(v)->u.i)
#define gcvalue(v)      ((v)->u.gc)
#define strvalue(v)     ((Str *)(v)->u.gc)
#define tabvalue(v)     ((Table *)(v)->u.gc)
#define lclvalue(v)     ((LClosure *)(v)->u.gc)
#define cclvalue(v)     ((CClosure *)(v)->u.gc)
#define udvalue(v)      ((Udata *)(v)->u.gc)
#define thvalue(v)      ((lua_State *)(v)->u.gc)
#define fvalue(v)       ((v)->u.f)

#define truthy(v)       (!((v)->tt == T_NIL || ((v)->tt == T_BOOL && (v)->u.i == 0)))

static inline Value mknil(void)            { Value v; v.tt = T_NIL; v.u.i = 0; return v; }
static inline Value mkbool(int b)          { Value v; v.tt = T_BOOL; v.u.i = (b != 0); return v; }
static inline Value mkint(lu_Integer i)    { Value v; v.tt = T_INT; v.u.i = i; return v; }
static inline Value mkflt(lu_Number n)     { Value v; v.tt = T_FLT; v.u.n = n; return v; }
static inline Value mklcf(CFn f)           { Value v; v.tt = T_LCF; v.u.f = f; return v; }
static inline Value mkgc(int tt, void *o)  { Value v; v.tt = tt; v.u.gc = (GCObj *)o; return v; }

/* ------------------------------------------------------------- gc objects */
struct GCObj {
  GCObj *next;
  uint8_t type;    /* T_STR, T_TAB, ... */
  uint8_t mark;    /* gc colour */
};

struct Str {
  GCObj h;
  uint32_t hash;
  uint32_t reserved;    /* index+1 of reserved word, 0 otherwise */
  size_t len;
  char s[1];            /* payload, NUL terminated */
};
#define strdata(ts)  ((ts)->s)

typedef struct Node {
  Value key;
  Value val;
} Node;

struct Table {
  GCObj h;
  Value *arr;            /* array part: indices 1..asize */
  uint32_t asize;
  Node *node;            /* hash part, power of two, or NULL */
  uint32_t nsize;
  uint32_t nuse;         /* occupied slots (including dead keys) */
  uint32_t nlive;        /* slots with non-nil values */
  Table *meta;
  uint8_t flags;         /* cache of absent metamethods */
};

typedef struct LocVar { Str *name; int startpc, endpc; } LocVar;
typedef struct UpvalDesc { Str *name; uint8_t instack; int idx; } UpvalDesc;

/* name hints let us produce "(local 'x')" style error suffixes */
enum { HN_NONE = 0, HN_LOCAL, HN_GLOBAL, HN_FIELD, HN_UPVAL, HN_METHOD,
       HN_CONST, HN_FORITER };
typedef struct NameHint { int pc; uint8_t slot; uint8_t kind; Str *name; } NameHint;

typedef struct Instr { uint8_t op; uint8_t a; int32_t b; int32_t c; } Instr;

struct Proto {
  GCObj h;
  Instr *code;    int ncode;
  Value *k;       int nk;
  Proto **p;      int np;
  int *lineinfo;
  LocVar *locvars;  int nlocvars;
  UpvalDesc *upvals; int nupvals;
  NameHint *hints;  int nhints;
  int numparams;
  int is_vararg;
  int maxstack;
  int linedefined, lastlinedefined;
  Str *source;
};

struct LClosure {
  GCObj h;
  Proto *p;
  int nupvals;
  Upval *upvals[1];
};

struct CClosure {
  GCObj h;
  CFn fn;
  int nupvals;
  Value upvals[1];
};

struct Upval {
  GCObj h;
  Value *v;          /* points to stack slot or to &u.closed */
  lua_State *owner;  /* thread whose stack holds it while open */
  int stkidx;        /* stack index while open */
  struct Upval *unext;
  Value closed;
};

struct Udata {
  GCObj h;
  Table *meta;
  size_t len;
  int nuser;
  Value user[4];
  void *data;        /* points into payload */
  char payload[1];
};

/* ------------------------------------------------------------- call frames */
enum { CIST_C = 1, CIST_TAIL = 2, CIST_HOOKED = 4, CIST_FIN = 8, CIST_RESET = 16 };

typedef struct CallInfo {
  int func;        /* stack index of the called object */
  int base;        /* stack index of first local */
  int top;         /* stack limit for this frame */
  int pc;          /* next instruction (Lua frames) */
  int nresults;
  int nextra;      /* extra vararg args stored below base */
  int flags;
  LClosure *cl;    /* NULL for C frames */
  const char *cfname;   /* diagnostic name for some C frames */
  struct CallInfo *prev, *next;
} CallInfo;

/* ---------------------------------------------------------------- threads */
enum { CO_OK = 0, CO_SUSPENDED, CO_RUNNING, CO_NORMAL, CO_DEAD };

typedef struct ErrJmp {
  jmp_buf b;
  volatile int status;
  struct ErrJmp *prev;
  int nCcalls;
} ErrJmp;

struct lua_State {
  GCObj h;
  GlobalState *G;
  Value *stack;
  int stacksize;
  int top;              /* first free slot */
  CallInfo base_ci;
  CallInfo *ci;
  Upval *openupval;
  ErrJmp *errjmp;
  int status;
  int nCcalls;
  int nny;              /* number of non-yieldable calls */
  lua_State *resumer;
  void *costack;        /* machine stack for coroutines */
  size_t costacksize;
  void *coctx;          /* ucontext_t * */
  void *retctx;         /* ucontext_t * of the resumer */
  int coentered;
  Value errval;         /* in-flight error object */
  int nresumeargs;
  int tbclist;          /* stack index of innermost to-be-closed slot + 1, 0 if none */
  int *tbcstack; int ntbc, tbccap;
};

/* metamethod events */
enum {
  MM_INDEX, MM_NEWINDEX, MM_GC, MM_MODE, MM_LEN, MM_EQ,
  MM_ADD, MM_SUB, MM_MUL, MM_MOD, MM_POW, MM_DIV, MM_IDIV,
  MM_BAND, MM_BOR, MM_BXOR, MM_SHL, MM_SHR,
  MM_UNM, MM_BNOT, MM_LT, MM_LE, MM_CONCAT, MM_CALL, MM_CLOSE,
  MM_TOSTRING, MM_NAME, MM_METATABLE, MM_PAIRS, MM_N
};

struct GlobalState {
  GCObj *allgc;
  size_t totalbytes;
  size_t gcthreshold;
  int gcrunning;
  int gcstate;          /* 0 = incremental, 1 = generational */
  int gcstp;            /* stop count */
  int gcemergency;
  Str **strtab;         /* interning table for short strings */
  uint32_t strtabsize;
  uint32_t nstr;
  uint32_t seed;
  Table *registry;
  Table *globals;
  Str *mmnames[MM_N];
  Str *typenames[T_NTYPES];
  Table *strmeta;       /* metatable for strings */
  lua_State *mainthread;
  lua_State *cur;       /* running thread */
  Value fixed[64]; int nfixed;   /* extra roots */
  GCObj *tobefnz;       /* objects with finalizers pending */
  Table *weakrefs;
  int panic;
  uint64_t rngstate[4];
  int warnon;
  char *warnbuf; size_t warnlen, warncap;
  int inwarn;
  const char *progname;
  int caughtsig;
};

/* --------------------------------------------------------------- statuses */
enum { LU_OK = 0, LU_YIELD, LU_ERRRUN, LU_ERRSYNTAX, LU_ERRMEM, LU_ERRERR };

/* ------------------------------------------------------------------ memory */
void *lu_alloc(lua_State *L, size_t n);
void *lu_realloc(lua_State *L, void *p, size_t oldn, size_t newn);
void  lu_free(lua_State *L, void *p, size_t n);
#define lu_new(L,t)  ((t *)lu_alloc(L, sizeof(t)))
void *lu_growvec(lua_State *L, void *v, int *cap, int need, size_t esz);

/* ------------------------------------------------------------------ strings */
Str *lu_newlstr(lua_State *L, const char *s, size_t len);
Str *lu_newstr(lua_State *L, const char *s);
Value lu_strvalue(lua_State *L, const char *s);
uint32_t lu_hashstr(const char *s, size_t len, uint32_t seed);
int lu_streq(Str *a, Str *b);
Str *lu_strfmt(lua_State *L, const char *fmt, ...);
Str *lu_strvfmt(lua_State *L, const char *fmt, va_list ap);

/* ------------------------------------------------------------------- tables */
Table *lu_newtable(lua_State *L);
Table *lu_newtable_sized(lua_State *L, int narr, int nrec);
const Value *lu_gettable_raw(Table *t, const Value *k);
const Value *lu_getstr(Table *t, Str *k);
const Value *lu_getint(Table *t, lu_Integer k);
void lu_settable_raw(lua_State *L, Table *t, const Value *k, Value v);
void lu_setstr(lua_State *L, Table *t, Str *k, Value v);
void lu_setint(lua_State *L, Table *t, lu_Integer k, Value v);
lu_Integer lu_tablen(Table *t);
int lu_next(lua_State *L, Table *t, Value *key, Value *val);
void lu_freetable(lua_State *L, Table *t);
void lu_resizearray(lua_State *L, Table *t, int n);

/* ------------------------------------------------------------------ objects */
Proto *lu_newproto(lua_State *L);
LClosure *lu_newlclosure(lua_State *L, int n);
CClosure *lu_newcclosure(lua_State *L, CFn fn, int n);
Udata *lu_newudata(lua_State *L, size_t sz, int nuser);
lua_State *lu_newthread(lua_State *L);

/* --------------------------------------------------------------- conversion */
int lu_tointeger(const Value *v, lu_Integer *out);      /* with string coercion */
int lu_tointeger_strict(const Value *v, lu_Integer *out);
int lu_tonumber(const Value *v, lu_Number *out);
int lu_str2num(const char *s, size_t len, Value *out);
int lu_flt2int(lu_Number n, lu_Integer *out, int mode);  /* mode 0: exact */
size_t lu_num2str(char *buf, size_t sz, const Value *v);
const char *lu_typename(const Value *v);
const char *lu_typenamek(int tt);

/* ---------------------------------------------------------------- VM / calls */
void lu_pushv(lua_State *L, Value v);
void lu_checkstack(lua_State *L, int n);
void lu_growstack(lua_State *L, int n);
#define S(L,i)   ((L)->stack[i])

int  lu_call(lua_State *L, int funcidx, int nargs, int nresults);
int  lu_pcall(lua_State *L, int funcidx, int nargs, int nresults, int msghidx);
void lu_callv(lua_State *L, Value fn, const Value *args, int nargs, int nres, Value *out);
void lu_error(lua_State *L, const char *fmt, ...);       /* adds position */
void lu_throwv(lua_State *L, Value v);
void lu_throw(lua_State *L, int status);
void lu_rterror(lua_State *L, const char *fmt, ...);     /* no position added */

Value lu_getmetafield(lua_State *L, const Value *v, int ev);
Table *lu_getmetatable(lua_State *L, const Value *v);
void lu_gettable(lua_State *L, const Value *t, const Value *k, Value *out);
void lu_settable(lua_State *L, const Value *t, const Value *k, const Value *v);
void lu_arith(lua_State *L, int op, const Value *a, const Value *b, Value *out);
int  lu_equalobj(lua_State *L, const Value *a, const Value *b);
int  lu_lessthan(lua_State *L, const Value *a, const Value *b);
int  lu_lessequal(lua_State *L, const Value *a, const Value *b);
void lu_concat(lua_State *L, int n);   /* concat top n stack values */
void lu_objlen(lua_State *L, const Value *v, Value *out);
Str *lu_tostring(lua_State *L, const Value *v);   /* honours __tostring */
Str *lu_tostr_basic(lua_State *L, const Value *v);

/* arithmetic op codes shared by VM and API */
enum { AR_ADD, AR_SUB, AR_MUL, AR_MOD, AR_POW, AR_DIV, AR_IDIV,
       AR_BAND, AR_BOR, AR_BXOR, AR_SHL, AR_SHR, AR_UNM, AR_BNOT };

/* ------------------------------------------------------------------- state */
lua_State *lu_newstate(void);
void lu_closestate(lua_State *L);
void lu_openlibs(lua_State *L);

/* --------------------------------------------------------------- gc control */
void lu_gcstep(lua_State *L);
void lu_fullgc(lua_State *L);
void lu_freeobj(lua_State *L, GCObj *o);
void lu_markvalue(GlobalState *g, const Value *v);
void lu_markobj(GlobalState *g, GCObj *o);
void lu_checkgc(lua_State *L);

/* -------------------------------------------------------------- compilation */
int lu_load(lua_State *L, const char *chunk, size_t len, const char *chunkname,
            const char *mode, Value env, Value *out, Str **errmsg);
Proto *lu_parse(lua_State *L, const char *buf, size_t len, const char *chunkname);
Str *lu_dumpproto(lua_State *L, Proto *p, int strip);
Proto *lu_undump(lua_State *L, const char *buf, size_t len, const char *chunkname);

/* ------------------------------------------------------------------ helpers */
void lu_chunkid(char *out, const char *source, size_t bufflen);
int  lu_currentline(lua_State *L, CallInfo *ci);
const char *lu_funcnamefromcall(lua_State *L, CallInfo *ci, const char **name);
Str *lu_traceback(lua_State *L, lua_State *L1, const char *msg, int level);
void lu_where(lua_State *L, int level, char *buf, size_t sz);

/* argument checking helpers (used by libraries) */
int  lu_nargs(lua_State *L);
Value *lu_arg(lua_State *L, int i);      /* 1-based; nil sentinel if missing */
int  lu_isnoneornil(lua_State *L, int i);
lu_Integer lu_checkint(lua_State *L, int i);
lu_Number  lu_checknum(lua_State *L, int i);
const char *lu_checklstr(lua_State *L, int i, size_t *len);
Str *lu_checkstrobj(lua_State *L, int i);
Table *lu_checktable(lua_State *L, int i);
Value *lu_checkany(lua_State *L, int i);
lu_Integer lu_optint(lua_State *L, int i, lu_Integer def);
lu_Number  lu_optnum(lua_State *L, int i, lu_Number def);
const char *lu_optlstr(lua_State *L, int i, const char *def, size_t *len);
int lu_checkopt(lua_State *L, int i, const char *def, const char *const opts[]);
void lu_argerror(lua_State *L, int n, const char *msg);
void lu_typeerror(lua_State *L, int n, const char *want);
void lu_argcheck(lua_State *L, int cond, int n, const char *msg);
int  lu_toboolean(lua_State *L, int i);

/* push helpers: results are pushed on the stack and the count returned */
void lu_pushnil(lua_State *L);
void lu_pushint(lua_State *L, lu_Integer i);
void lu_pushnum(lua_State *L, lu_Number n);
void lu_pushbool(lua_State *L, int b);
void lu_pushstr(lua_State *L, const char *s);
void lu_pushlstr(lua_State *L, const char *s, size_t len);
void lu_pushfstr(lua_State *L, const char *fmt, ...);
void lu_pushcfn(lua_State *L, CFn f);
void lu_pushtable(lua_State *L, Table *t);
void lu_pushclosure(lua_State *L, CFn f, const Value *ups, int n);

/* registration */
typedef struct luLReg { const char *name; CFn fn; } luLReg;
void lu_setfuncs(lua_State *L, Table *t, const luLReg *l);
Table *lu_newlib(lua_State *L, const char *name, const luLReg *l);

/* dynamic byte buffer used to build strings */
typedef struct Buf { char *b; size_t n, cap; char init[256]; lua_State *L; } Buf;
void buf_init(lua_State *L, Buf *b);
void buf_addlstr(Buf *b, const char *s, size_t l);
void buf_addstr(Buf *b, const char *s);
void buf_addch(Buf *b, int c);
void buf_addvalue(Buf *b, const Value *v);
void buf_free(Buf *b);
#define buf_ensure(b,n) buf_prep(b,n)
char *buf_prep(Buf *b, size_t n);

/* library entry points */
int luopen_base(lua_State *L);
int luopen_string(lua_State *L);
int luopen_table(lua_State *L);
int luopen_math(lua_State *L);
int luopen_io(lua_State *L);
int luopen_os(lua_State *L);
int luopen_coroutine(lua_State *L);
int luopen_utf8(lua_State *L);
int luopen_debug(lua_State *L);
int luopen_package(lua_State *L);

/* coroutine plumbing implemented in vm.c */
int lu_resume(lua_State *L, lua_State *co, int nargs, int *nres);
int lu_yield(lua_State *L, int nvals);
int lu_closethread(lua_State *L, lua_State *co, int reset);

/* to-be-closed variables */
void lu_pushtbc(lua_State *L, int idx);
int  lu_closetbc(lua_State *L, int level, int status);

/* misc used across modules */
int lu_getsubtable(lua_State *L, Table *t, const char *name, Table **out);
Value lu_registryfield(lua_State *L, const char *name);
void lu_setregistryfield(lua_State *L, const char *name, Value v);

extern const char *const lu_mmnames[MM_N];

#endif

