/*
** object.c -- values, strings, tables, conversions.
*/
#include <string.h>
#include <stdlib.h>
#include <stdarg.h>
#include <math.h>
#include <ctype.h>
#include <errno.h>
#include "lu.h"

/* ------------------------------------------------------------------ memory */

static void memerror(lua_State *L) {
  if (L) {
    L->errval = lu_strvalue(L, "not enough memory");
    lu_throw(L, LU_ERRMEM);
  }
  fprintf(stderr, "lua: not enough memory\n");
  exit(1);
}

void *lu_alloc(lua_State *L, size_t n) {
  void *p;
  if (n == 0) return NULL;
  p = malloc(n);
  if (p == NULL) { lu_fullgc(L); p = malloc(n); if (p == NULL) memerror(L); }
  if (L) L->G->totalbytes += n;
  return p;
}

void *lu_realloc(lua_State *L, void *p, size_t oldn, size_t newn) {
  void *np;
  if (newn == 0) { free(p); if (L) L->G->totalbytes -= oldn; return NULL; }
  np = realloc(p, newn);
  if (np == NULL) { lu_fullgc(L); np = realloc(p, newn); if (np == NULL) memerror(L); }
  if (L) L->G->totalbytes += newn - oldn;
  return np;
}

void lu_free(lua_State *L, void *p, size_t n) {
  if (p == NULL) return;
  free(p);
  if (L) L->G->totalbytes -= n;
}

void *lu_growvec(lua_State *L, void *v, int *cap, int need, size_t esz) {
  int nc = *cap;
  if (need <= nc) return v;
  if (nc == 0) nc = 4;
  while (nc < need) nc *= 2;
  v = lu_realloc(L, v, (size_t)*cap * esz, (size_t)nc * esz);
  *cap = nc;
  return v;
}

/* ----------------------------------------------------------------- strings */

uint32_t lu_hashstr(const char *s, size_t len, uint32_t seed) {
  uint32_t h = seed ^ (uint32_t)len;
  size_t i;
  for (i = 0; i < len; i++)
    h ^= ((h << 5) + (h >> 2) + (unsigned char)s[i]);
  return h;
}

#define SHORTLIMIT 40

static void growstrtab(lua_State *L) {
  GlobalState *g = L->G;
  uint32_t nsize = g->strtabsize * 2;
  Str **nt = (Str **)lu_alloc(L, nsize * sizeof(Str *));
  uint32_t i;
  for (i = 0; i < nsize; i++) nt[i] = NULL;
  for (i = 0; i < g->strtabsize; i++) {
    Str *s = g->strtab[i];
    while (s) {
      Str *nx = (Str *)s->h.next;
      uint32_t idx = s->hash & (nsize - 1);
      s->h.next = (GCObj *)nt[idx];
      nt[idx] = s;
      s = nx;
    }
  }
  lu_free(L, g->strtab, g->strtabsize * sizeof(Str *));
  g->strtab = nt;
  g->strtabsize = nsize;
}

static Str *allocstr(lua_State *L, const char *s, size_t len, uint32_t h) {
  Str *ts = (Str *)lu_alloc(L, sizeof(Str) + len);
  ts->h.type = T_STR;
  ts->h.mark = 0;
  ts->hash = h;
  ts->reserved = 0;
  ts->len = len;
  if (len) memcpy(ts->s, s, len);
  ts->s[len] = '\0';
  return ts;
}

Str *lu_newlstr(lua_State *L, const char *s, size_t len) {
  GlobalState *g = L->G;
  if (len <= SHORTLIMIT) {
    uint32_t h = lu_hashstr(s, len, g->seed);
    uint32_t idx = h & (g->strtabsize - 1);
    Str *o;
    for (o = g->strtab[idx]; o != NULL; o = (Str *)o->h.next) {
      if (o->len == len && memcmp(o->s, s, len) == 0) {
        if (o->h.mark == 2) o->h.mark = 0;   /* resurrect */
        return o;
      }
    }
    o = allocstr(L, s, len, h);
    o->h.next = (GCObj *)g->strtab[idx];
    g->strtab[idx] = o;
    g->nstr++;
    if (g->nstr > g->strtabsize) growstrtab(L);
    return o;
  } else {
    Str *o = allocstr(L, s, len, lu_hashstr(s, len, g->seed));
    o->h.next = g->allgc;
    g->allgc = (GCObj *)o;
    return o;
  }
}

Str *lu_newstr(lua_State *L, const char *s) {
  return lu_newlstr(L, s, strlen(s));
}

Value lu_strvalue(lua_State *L, const char *s) {
  return mkgc(T_STR, lu_newlstr(L, s, strlen(s)));
}

int lu_streq(Str *a, Str *b) {
  if (a == b) return 1;
  if (a->len != b->len) return 0;
  if (a->len <= SHORTLIMIT) return 0;   /* interned: pointer compare suffices */
  return memcmp(a->s, b->s, a->len) == 0;
}

/* ------------------------------------------------------------- conversions */

/* Convert a float to string following the reference: try "%.14g"; if it does
** not round-trip use "%.17g"; then if the result looks like an integer append
** ".0". */
static size_t flt2str(char *buf, size_t sz, lu_Number n) {
  int len = snprintf(buf, sz, "%.14g", n);
  if (len > 0 && (size_t)len < sz) {
    char *e;
    double back = strtod(buf, &e);
    if (*e != '\0' || back != n) {
      /* not exact: use full precision */
      if (!(n != n) && !(n == HUGE_VAL || n == -HUGE_VAL))
        len = snprintf(buf, sz, "%.17g", n);
    }
  }
  if (len > 0 && buf[strspn(buf, "-0123456789")] == '\0') {
    buf[len++] = '.';
    buf[len++] = '0';
    buf[len] = '\0';
  }
  return (size_t)len;
}

size_t lu_num2str(char *buf, size_t sz, const Value *v) {
  if (ttisint(v))
    return (size_t)snprintf(buf, sz, "%lld", (long long)ivalue(v));
  return flt2str(buf, sz, fltvalue(v));
}

int lu_flt2int(lu_Number n, lu_Integer *out, int mode) {
  lu_Number f = l_floor_(n);
  if (n != f) {                 /* not an integral value? */
    if (mode == 0) return 0;    /* fails if mode demands integral */
    else if (mode == 2) f += 1; /* ceil */
  }
  if (!(f >= -9223372036854775808.0 && f < 9223372036854775808.0)) return 0;
  *out = (lu_Integer)f;
  return 1;
}

int lu_tointeger_strict(const Value *v, lu_Integer *out) {
  if (ttisint(v)) { *out = ivalue(v); return 1; }
  if (ttisflt(v)) return lu_flt2int(fltvalue(v), out, 0);
  return 0;
}

int lu_tointeger(const Value *v, lu_Integer *out) {
  if (ttisint(v)) { *out = ivalue(v); return 1; }
  if (ttisflt(v)) return lu_flt2int(fltvalue(v), out, 0);
  if (ttisstr(v)) {
    Value tmp;
    Str *s = strvalue(v);
    if (lu_str2num(s->s, s->len, &tmp)) return lu_tointeger_strict(&tmp, out);
  }
  return 0;
}

int lu_tonumber(const Value *v, lu_Number *out) {
  if (ttisint(v)) { *out = (lu_Number)ivalue(v); return 1; }
  if (ttisflt(v)) { *out = fltvalue(v); return 1; }
  if (ttisstr(v)) {
    Value tmp;
    Str *s = strvalue(v);
    if (lu_str2num(s->s, s->len, &tmp)) { *out = nvalue(&tmp); return 1; }
  }
  return 0;
}

#define MAXNUMLEN 200

static const char *str2int(const char *s, lu_Integer *result) {
  lu_Unsigned a = 0;
  int empty = 1, neg;
  while (isspace((unsigned char)*s)) s++;
  neg = (*s == '-');
  if (*s == '-' || *s == '+') s++;
  if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
    s += 2;
    for (; isxdigit((unsigned char)*s); s++) {
      int d = isdigit((unsigned char)*s) ? *s - '0'
              : (tolower((unsigned char)*s) - 'a' + 10);
      a = a * 16 + (lu_Unsigned)d;
      empty = 0;
    }
  } else {
    for (; isdigit((unsigned char)*s); s++) {
      int d = *s - '0';
      if (a >= 922337203685477580ULL && (a > 922337203685477580ULL || d > 7))
        return NULL;   /* overflow: let the float path handle it */
      a = a * 10 + (lu_Unsigned)d;
      empty = 0;
    }
  }
  while (isspace((unsigned char)*s)) s++;
  if (empty || *s != '\0') return NULL;
  *result = neg ? (lu_Integer)(0u - a) : (lu_Integer)a;
  return s;
}

static const char *str2flt(const char *s, lu_Number *result) {
  char *end;
  const char *pm = strpbrk(s, ".xXnN");
  int mode = pm ? tolower((unsigned char)*pm) : 0;
  if (mode == 'n') return NULL;   /* reject inf/nan spellings */
  *result = strtod(s, &end);
  if (end == s) return NULL;
  while (isspace((unsigned char)*end)) end++;
  return (*end == '\0') ? end : NULL;
}

int lu_str2num(const char *s, size_t len, Value *out) {
  char buff[MAXNUMLEN + 1];
  lu_Integer i; lu_Number n;
  if (len != strlen(s)) return 0;         /* embedded zeros: not a number */
  if (len > MAXNUMLEN) return 0;
  memcpy(buff, s, len); buff[len] = '\0';
  if (str2int(buff, &i)) { *out = mkint(i); return 1; }
  if (str2flt(buff, &n)) { *out = mkflt(n); return 1; }
  return 0;
}

const char *lu_typenamek(int tt) {
  switch (tt) {
    case T_NIL: return "nil";
    case T_BOOL: return "boolean";
    case T_INT: case T_FLT: case T_NUM: return "number";
    case T_STR: return "string";
    case T_TAB: return "table";
    case T_LCF: case T_LCL: case T_CCL: case T_FUN: return "function";
    case T_USER: return "userdata";
    case T_THREAD: return "thread";
    default: return "no value";
  }
}

const char *lu_typename(const Value *v) { return lu_typenamek(v->tt); }

/* ------------------------------------------------------------------ tables */

static uint32_t hashint(lu_Integer i) {
  uint64_t u = (uint64_t)i;
  u ^= u >> 33; u *= 0xff51afd7ed558ccdULL;
  u ^= u >> 33; u *= 0xc4ceb9fe1a85ec53ULL;
  u ^= u >> 33;
  return (uint32_t)u;
}

static uint32_t hashvalue(const Value *k) {
  switch (k->tt) {
    case T_INT: return hashint(ivalue(k));
    case T_FLT: {
      lu_Number n = fltvalue(k);
      uint64_t bits; memcpy(&bits, &n, 8);
      if (n == 0) bits = 0;
      return hashint((lu_Integer)bits) ^ 0x9e3779b9u;
    }
    case T_STR: return strvalue(k)->hash;
    case T_BOOL: return bvalue(k) ? 0x51ed270bu : 0x2a5d1e3fu;
    case T_LCF: {
      uint64_t u = (uint64_t)(uintptr_t)k->u.f;
      return hashint((lu_Integer)u);
    }
    default: {
      uint64_t u = (uint64_t)(uintptr_t)k->u.gc;
      return hashint((lu_Integer)u);
    }
  }
}

static int rawkeyeq(const Value *a, const Value *b) {
  if (a->tt != b->tt) {
    if (a->tt == T_INT && b->tt == T_FLT) return 0;
    if (a->tt == T_FLT && b->tt == T_INT) return 0;
    return 0;
  }
  switch (a->tt) {
    case T_NIL: return 1;
    case T_BOOL: return bvalue(a) == bvalue(b);
    case T_INT: return ivalue(a) == ivalue(b);
    case T_FLT: return fltvalue(a) == fltvalue(b);
    case T_STR: return lu_streq(strvalue(a), strvalue(b));
    case T_LCF: return fvalue(a) == fvalue(b);
    default: return gcvalue(a) == gcvalue(b);
  }
}

Table *lu_newtable(lua_State *L) {
  Table *t = (Table *)lu_alloc(L, sizeof(Table));
  t->h.type = T_TAB; t->h.mark = 0;
  t->h.next = L->G->allgc; L->G->allgc = (GCObj *)t;
  t->arr = NULL; t->asize = 0;
  t->node = NULL; t->nsize = 0; t->nuse = 0; t->nlive = 0;
  t->meta = NULL; t->flags = 0;
  return t;
}

static uint32_t ceilpow2(uint32_t n) {
  uint32_t p = 1;
  while (p < n) { p <<= 1; if (p == 0) return 0x80000000u; }
  return p;
}

static void setnodesize(lua_State *L, Table *t, uint32_t size) {
  uint32_t i;
  if (size == 0) { t->node = NULL; t->nsize = 0; t->nuse = 0; return; }
  t->node = (Node *)lu_alloc(L, size * sizeof(Node));
  t->nsize = size;
  t->nuse = 0;
  for (i = 0; i < size; i++) { t->node[i].key = mknil(); t->node[i].val = mknil(); }
}

void lu_resizearray(lua_State *L, Table *t, int n) {
  uint32_t i, old = t->asize;
  if ((uint32_t)n == old) return;
  t->arr = (Value *)lu_realloc(L, t->arr, old * sizeof(Value), (size_t)n * sizeof(Value));
  for (i = old; i < (uint32_t)n; i++) t->arr[i] = mknil();
  t->asize = (uint32_t)n;
}

/* normalise a key: float with an exact integer value becomes an integer */
static int normkey(const Value *k, Value *out) {
  if (ttisflt(k)) {
    lu_Integer i;
    if (lu_flt2int(fltvalue(k), &i, 0)) { *out = mkint(i); return 1; }
    if (fltvalue(k) != fltvalue(k)) return -1;    /* NaN */
  }
  *out = *k;
  return 1;
}

static Node *findnode(Table *t, const Value *k, uint32_t h) {
  uint32_t mask, i;
  if (t->nsize == 0) return NULL;
  mask = t->nsize - 1;
  i = h & mask;
  for (;;) {
    Node *n = &t->node[i];
    if (ttisnil(&n->key)) return NULL;
    if (rawkeyeq(&n->key, k)) return n;
    i = (i + 1) & mask;
  }
}

const Value *lu_getint(Table *t, lu_Integer k) {
  static const Value nilv = { {0}, T_NIL };
  if (k >= 1 && (lu_Unsigned)k <= t->asize) return &t->arr[k - 1];
  {
    Value kv = mkint(k);
    Node *n = findnode(t, &kv, hashint(k));
    return n ? &n->val : &nilv;
  }
}

const Value *lu_getstr(Table *t, Str *k) {
  static const Value nilv = { {0}, T_NIL };
  Value kv = mkgc(T_STR, k);
  Node *n = findnode(t, &kv, k->hash);
  return n ? &n->val : &nilv;
}

const Value *lu_gettable_raw(Table *t, const Value *key) {
  static const Value nilv = { {0}, T_NIL };
  Value k;
  if (normkey(key, &k) < 0) return &nilv;
  if (ttisint(&k)) return lu_getint(t, ivalue(&k));
  if (ttisnil(&k)) return &nilv;
  {
    Node *n = findnode(t, &k, hashvalue(&k));
    return n ? &n->val : &nilv;
  }
}

/* collect all integer keys, compute a good array size */
typedef struct KeyVec { lu_Integer *v; int n, cap; } KeyVec;

static void kv_add(lua_State *L, KeyVec *kv, lu_Integer k) {
  if (kv->n == kv->cap) {
    int nc = kv->cap ? kv->cap * 2 : 32;
    kv->v = (lu_Integer *)lu_realloc(L, kv->v, (size_t)kv->cap * sizeof(lu_Integer),
                                     (size_t)nc * sizeof(lu_Integer));
    kv->cap = nc;
  }
  kv->v[kv->n++] = k;
}

static int cmpkey(const void *a, const void *b) {
  lu_Integer x = *(const lu_Integer *)a, y = *(const lu_Integer *)b;
  return (x < y) ? -1 : (x > y) ? 1 : 0;
}

static void rehash(lua_State *L, Table *t, const Value *extrakey) {
  KeyVec kv; uint32_t i;
  uint32_t nothers = 0, newasize = 0, newnsize;
  Node *oldnode = t->node; uint32_t oldnsize = t->nsize;
  Value *oldarr = t->arr; uint32_t oldasize = t->asize;
  kv.v = NULL; kv.n = 0; kv.cap = 0;
  for (i = 0; i < oldasize; i++)
    if (!ttisnil(&oldarr[i])) kv_add(L, &kv, (lu_Integer)i + 1);
  for (i = 0; i < oldnsize; i++) {
    Node *n = &oldnode[i];
    if (!ttisnil(&n->key) && !ttisnil(&n->val)) {
      if (ttisint(&n->key) && ivalue(&n->key) >= 1) kv_add(L, &kv, ivalue(&n->key));
      else nothers++;
    }
  }
  if (extrakey) {
    if (ttisint(extrakey) && ivalue(extrakey) >= 1) kv_add(L, &kv, ivalue(extrakey));
    else nothers++;
  }
  if (kv.n > 0) {
    int j; lu_Integer best = 0;
    qsort(kv.v, (size_t)kv.n, sizeof(lu_Integer), cmpkey);
    for (j = 0; j < kv.n; j++) {
      lu_Integer n = kv.v[j];
      if (n > 0 && n <= 0x7ffffff0 && (lu_Integer)(j + 1) * 2 > n) best = n;
    }
    newasize = (uint32_t)best;
    /* count keys that will not fit in the array part */
    for (j = 0; j < kv.n; j++)
      if (kv.v[j] > (lu_Integer)newasize) nothers++;
  }
  /* geometric growth to keep appends amortised */
  if (newasize > 0) {
    uint32_t cap = ceilpow2(newasize);
    if (cap > newasize && newasize >= 1024) {
      /* avoid gross over-allocation for very large arrays */
      uint32_t alt = newasize + newasize / 4 + 1;
      cap = (alt < cap) ? alt : cap;
    }
    newasize = cap;
  }
  lu_free(L, kv.v, (size_t)kv.cap * sizeof(lu_Integer));
  newnsize = nothers ? ceilpow2(nothers + nothers / 2 + 1) : 0;
  if (newnsize && newnsize < 4) newnsize = 4;

  /* build the new table */
  t->arr = NULL; t->asize = 0;
  t->node = NULL; t->nsize = 0; t->nuse = 0; t->nlive = 0;
  if (newasize) lu_resizearray(L, t, (int)newasize);
  setnodesize(L, t, newnsize);
  for (i = 0; i < oldasize; i++)
    if (!ttisnil(&oldarr[i])) lu_setint(L, t, (lu_Integer)i + 1, oldarr[i]);
  for (i = 0; i < oldnsize; i++) {
    Node *n = &oldnode[i];
    if (!ttisnil(&n->key) && !ttisnil(&n->val))
      lu_settable_raw(L, t, &n->key, n->val);
  }
  lu_free(L, oldarr, oldasize * sizeof(Value));
  lu_free(L, oldnode, oldnsize * sizeof(Node));
}

static void insertnode(lua_State *L, Table *t, const Value *k, uint32_t h, Value v) {
  uint32_t mask, i;
  if (t->nsize == 0 || (t->nuse + 1) * 4 > t->nsize * 3) {
    rehash(L, t, k);
    lu_settable_raw(L, t, k, v);
    return;
  }
  mask = t->nsize - 1;
  i = h & mask;
  while (!ttisnil(&t->node[i].key)) i = (i + 1) & mask;
  t->node[i].key = *k;
  t->node[i].val = v;
  t->nuse++;
  t->nlive++;
}

void lu_setint(lua_State *L, Table *t, lu_Integer k, Value v) {
  if (k >= 1 && (lu_Unsigned)k <= t->asize) { t->arr[k - 1] = v; return; }
  {
    Value kv = mkint(k);
    uint32_t h = hashint(k);
    Node *n = findnode(t, &kv, h);
    if (n) {
      if (ttisnil(&n->val) && !ttisnil(&v)) t->nlive++;
      else if (!ttisnil(&n->val) && ttisnil(&v)) t->nlive--;
      n->val = v;
      return;
    }
    if (ttisnil(&v)) return;   /* no need to create the entry */
    /* an integer just past the array may grow the array part */
    if (k >= 1 && (lu_Unsigned)k == (lu_Unsigned)t->asize + 1) {
      rehash(L, t, &kv);
      lu_setint(L, t, k, v);
      return;
    }
    insertnode(L, t, &kv, h, v);
  }
}

void lu_setstr(lua_State *L, Table *t, Str *k, Value v) {
  Value kv = mkgc(T_STR, k);
  Node *n = findnode(t, &kv, k->hash);
  if (n) {
    if (ttisnil(&n->val) && !ttisnil(&v)) t->nlive++;
    else if (!ttisnil(&n->val) && ttisnil(&v)) t->nlive--;
    n->val = v;
    return;
  }
  if (ttisnil(&v)) return;
  insertnode(L, t, &kv, k->hash, v);
}

void lu_settable_raw(lua_State *L, Table *t, const Value *key, Value v) {
  Value k;
  normkey(key, &k);
  if (ttisint(&k)) { lu_setint(L, t, ivalue(&k), v); return; }
  if (ttisstr(&k)) { lu_setstr(L, t, strvalue(&k), v); return; }
  {
    uint32_t h = hashvalue(&k);
    Node *n = findnode(t, &k, h);
    if (n) {
      if (ttisnil(&n->val) && !ttisnil(&v)) t->nlive++;
      else if (!ttisnil(&n->val) && ttisnil(&v)) t->nlive--;
      n->val = v;
      return;
    }
    if (ttisnil(&v)) return;
    insertnode(L, t, &k, h, v);
  }
}

lu_Integer lu_tablen(Table *t) {
  if (t->asize > 0 && ttisnil(&t->arr[t->asize - 1])) {
    /* there is a nil at the end: binary search for a border */
    uint32_t lo = 0, hi = t->asize;
    while (hi - lo > 1) {
      uint32_t m = (lo + hi) / 2;
      if (ttisnil(&t->arr[m - 1])) hi = m; else lo = m;
    }
    return (lu_Integer)lo;
  }
  if (t->nsize == 0) return (lu_Integer)t->asize;
  {
    /* unbounded search in the hash part */
    lu_Integer i = (lu_Integer)t->asize, j = i + 1;
    while (!ttisnil(lu_getint(t, j))) {
      i = j;
      if (j > (lu_Integer)1 << 40) {      /* degenerate: linear search */
        i = 1;
        while (!ttisnil(lu_getint(t, i))) i++;
        return i - 1;
      }
      j *= 2;
    }
    while (j - i > 1) {
      lu_Integer m = i + (j - i) / 2;
      if (ttisnil(lu_getint(t, m))) j = m; else i = m;
    }
    return i;
  }
}

int lu_next(lua_State *L, Table *t, Value *key, Value *val) {
  uint32_t i = 0;
  (void)L;
  if (ttisnil(key)) i = 0;
  else {
    Value k;
    normkey(key, &k);
    if (ttisint(&k) && ivalue(&k) >= 1 && (lu_Unsigned)ivalue(&k) <= t->asize)
      i = (uint32_t)ivalue(&k);
    else {
      Node *n = findnode(t, &k, hashvalue(&k));
      if (n == NULL) return -1;    /* invalid key */
      i = t->asize + (uint32_t)(n - t->node) + 1;
    }
  }
  for (; i < t->asize; i++) {
    if (!ttisnil(&t->arr[i])) {
      *key = mkint((lu_Integer)i + 1);
      *val = t->arr[i];
      return 1;
    }
  }
  for (i = i - t->asize; i < t->nsize; i++) {
    if (!ttisnil(&t->node[i].key) && !ttisnil(&t->node[i].val)) {
      *key = t->node[i].key;
      *val = t->node[i].val;
      return 1;
    }
  }
  return 0;
}

void lu_freetable(lua_State *L, Table *t) {
  lu_free(L, t->arr, t->asize * sizeof(Value));
  lu_free(L, t->node, t->nsize * sizeof(Node));
}

Table *lu_newtable_sized(lua_State *L, int narr, int nrec) {
  Table *t = lu_newtable(L);
  if (narr > 0) lu_resizearray(L, t, narr);
  if (nrec > 0) setnodesize(L, t, ceilpow2((uint32_t)(nrec + nrec / 2 + 1)));
  return t;
}

/* ---------------------------------------------------------------- closures */

Proto *lu_newproto(lua_State *L) {
  Proto *p = (Proto *)lu_alloc(L, sizeof(Proto));
  memset(p, 0, sizeof(Proto));
  p->h.type = T_PROTO; p->h.mark = 0;
  p->h.next = L->G->allgc; L->G->allgc = (GCObj *)p;
  return p;
}

LClosure *lu_newlclosure(lua_State *L, int n) {
  LClosure *c = (LClosure *)lu_alloc(L, sizeof(LClosure) + (n > 0 ? (n - 1) : 0) * sizeof(Upval *));
  int i;
  c->h.type = T_LCL; c->h.mark = 0;
  c->h.next = L->G->allgc; L->G->allgc = (GCObj *)c;
  c->p = NULL; c->nupvals = n;
  for (i = 0; i < n; i++) c->upvals[i] = NULL;
  return c;
}

CClosure *lu_newcclosure(lua_State *L, CFn fn, int n) {
  CClosure *c = (CClosure *)lu_alloc(L, sizeof(CClosure) + (n > 0 ? (n - 1) : 0) * sizeof(Value));
  int i;
  c->h.type = T_CCL; c->h.mark = 0;
  c->h.next = L->G->allgc; L->G->allgc = (GCObj *)c;
  c->fn = fn; c->nupvals = n;
  for (i = 0; i < n; i++) c->upvals[i] = mknil();
  return c;
}

Udata *lu_newudata(lua_State *L, size_t sz, int nuser) {
  Udata *u = (Udata *)lu_alloc(L, sizeof(Udata) + sz);
  int i;
  u->h.type = T_USER; u->h.mark = 0;
  u->h.next = L->G->allgc; L->G->allgc = (GCObj *)u;
  u->meta = NULL; u->len = sz; u->nuser = nuser;
  for (i = 0; i < 4; i++) u->user[i] = mknil();
  u->data = u->payload;
  memset(u->payload, 0, sz + 1);
  return u;
}

/* ------------------------------------------------------------------ buffers */

void buf_init(lua_State *L, Buf *b) {
  b->L = L; b->b = b->init; b->n = 0; b->cap = sizeof(b->init);
}

char *buf_prep(Buf *b, size_t need) {
  if (b->n + need > b->cap) {
    size_t nc = b->cap * 2;
    while (nc < b->n + need) nc *= 2;
    if (b->b == b->init) {
      char *nb = (char *)lu_alloc(b->L, nc);
      memcpy(nb, b->init, b->n);
      b->b = nb;
    } else {
      b->b = (char *)lu_realloc(b->L, b->b, b->cap, nc);
    }
    b->cap = nc;
  }
  return b->b + b->n;
}

void buf_addlstr(Buf *b, const char *s, size_t l) {
  if (l == 0) return;
  memcpy(buf_prep(b, l), s, l);
  b->n += l;
}

void buf_addstr(Buf *b, const char *s) { buf_addlstr(b, s, strlen(s)); }

void buf_addch(Buf *b, int c) { *buf_prep(b, 1) = (char)c; b->n++; }

void buf_free(Buf *b) {
  if (b->b != b->init) lu_free(b->L, b->b, b->cap);
  b->b = b->init; b->cap = sizeof(b->init); b->n = 0;
}

/* ------------------------------------------------------------- mini printf */

Str *lu_strvfmt(lua_State *L, const char *fmt, va_list ap) {
  Buf b; Str *r;
  buf_init(L, &b);
  while (*fmt) {
    if (*fmt != '%') { buf_addch(&b, *fmt++); continue; }
    fmt++;
    switch (*fmt) {
      case 's': { const char *s = va_arg(ap, char *); buf_addstr(&b, s ? s : "(null)"); break; }
      case 'd': { char t[32]; int n = snprintf(t, sizeof(t), "%d", va_arg(ap, int)); buf_addlstr(&b, t, (size_t)n); break; }
      case 'I': { char t[40]; int n = snprintf(t, sizeof(t), "%lld", (long long)va_arg(ap, lu_Integer)); buf_addlstr(&b, t, (size_t)n); break; }
      case 'f': { char t[64]; Value v = mkflt(va_arg(ap, double)); size_t n = lu_num2str(t, sizeof(t), &v); buf_addlstr(&b, t, n); break; }
      case 'c': { buf_addch(&b, va_arg(ap, int)); break; }
      case 'p': { char t[40]; int n = snprintf(t, sizeof(t), "%p", va_arg(ap, void *)); buf_addlstr(&b, t, (size_t)n); break; }
      case 'S': { Str *s = va_arg(ap, Str *); buf_addlstr(&b, s->s, s->len); break; }
      case '%': buf_addch(&b, '%'); break;
      default: buf_addch(&b, '%'); buf_addch(&b, *fmt); break;
    }
    fmt++;
  }
  r = lu_newlstr(L, b.b, b.n);
  buf_free(&b);
  return r;
}

Str *lu_strfmt(lua_State *L, const char *fmt, ...) {
  va_list ap; Str *r;
  va_start(ap, fmt);
  r = lu_strvfmt(L, fmt, ap);
  va_end(ap);
  return r;
}

