/*
** lex.c -- lexical analyser
*/
#include <string.h>
#include <stdlib.h>
#include <ctype.h>
#include "lu.h"
#include "lex.h"

const char *const lex_tokens[] = {
  "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
  "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return",
  "then", "true", "until", "while",
  "//", "..", "...", "==", ">=", "<=", "~=", "<<", ">>", "::",
  "<eof>", "<number>", "<number>", "<name>", "<string>"
};

#define EOZ (-1)
#define curr(ls) ((ls)->current)

static void nextc(LexState *ls) {
  if (ls->p < ls->pend) ls->current = (unsigned char)*ls->p++;
  else ls->current = EOZ;
}

static void save(LexState *ls, int c) {
  buf_addch(&ls->buff, c);
}

static void save_and_next(LexState *ls) { save(ls, ls->current); nextc(ls); }

static int currIsNewline(LexState *ls) {
  return ls->current == '\n' || ls->current == '\r';
}

const char *lex_token2str(LexState *ls, int token) {
  if (token < TK_FIRST) {
    if (isprint(token))
      return strdata(lu_strfmt(ls->L, "'%c'", token));
    else
      return strdata(lu_strfmt(ls->L, "'<\\%d>'", token));
  } else {
    const char *s = lex_tokens[token - TK_FIRST];
    if (token < TK_EOS)
      return strdata(lu_strfmt(ls->L, "'%s'", s));
    else
      return s;
  }
}

static const char *txtToken(LexState *ls, int token) {
  switch (token) {
    case TK_NAME: case TK_STRING: case TK_FLT: case TK_INT:
      save(ls, '\0');
      return strdata(lu_strfmt(ls->L, "'%s'", ls->buff.b));
    default:
      return lex_token2str(ls, token);
  }
}

void lex_error(LexState *ls, const char *msg, int token) {
  char idbuf[64];
  lu_chunkid(idbuf, strdata(ls->source), sizeof(idbuf));
  if (token)
    msg = strdata(lu_strfmt(ls->L, "%s:%d: %s near %s", idbuf, ls->linenumber,
                            msg, txtToken(ls, token)));
  else
    msg = strdata(lu_strfmt(ls->L, "%s:%d: %s", idbuf, ls->linenumber, msg));
  ls->L->errval = lu_strvalue(ls->L, msg);
  lu_throw(ls->L, LU_ERRSYNTAX);
}

void lex_syntaxerror(LexState *ls, const char *msg) {
  lex_error(ls, msg, ls->t.token);
}

static void inclinenumber(LexState *ls) {
  int old = ls->current;
  nextc(ls);
  if (currIsNewline(ls) && ls->current != old) nextc(ls);
  if (++ls->linenumber >= INT32_MAX) lex_error(ls, "chunk has too many lines", 0);
}

void lex_setinput(lua_State *L, LexState *ls, const char *buf, size_t len, Str *source) {
  ls->L = L;
  ls->p = buf; ls->pend = buf + len;
  ls->source = source;
  ls->linenumber = 1;
  ls->lastline = 1;
  ls->t.token = TK_EOS;
  ls->lookahead.token = TK_EOS;
  ls->fs = NULL;
  ls->dyd = NULL;
  buf_init(L, &ls->buff);
  nextc(ls);
  /* skip an optional BOM */
  if (ls->current == 0xEF) {
    const char *save_p = ls->p;
    if (ls->pend - ls->p >= 2 && (unsigned char)ls->p[0] == 0xBB &&
        (unsigned char)ls->p[1] == 0xBF) {
      ls->p += 2; nextc(ls);
    } else { ls->p = save_p; }
  }
  /* skip a shebang line */
  if (ls->current == '#') {
    while (ls->current != EOZ && !currIsNewline(ls)) nextc(ls);
    if (ls->current != EOZ) inclinenumber(ls);
  }
}

static int check_next1(LexState *ls, int c) {
  if (ls->current == c) { nextc(ls); return 1; }
  return 0;
}

static int check_next2(LexState *ls, const char *set) {
  if (ls->current == set[0] || ls->current == set[1]) { save_and_next(ls); return 1; }
  return 0;
}

static int read_numeral(LexState *ls, SemInfo *seminfo) {
  Value v;
  const char *expo = "Ee";
  int first = ls->current;
  save_and_next(ls);
  if (first == '0' && check_next2(ls, "xX")) expo = "Pp";
  for (;;) {
    if (check_next2(ls, expo)) check_next2(ls, "-+");
    else if (isxdigit(ls->current) || ls->current == '.') save_and_next(ls);
    else break;
  }
  if (isalpha(ls->current) || ls->current == '_') save_and_next(ls);
  save(ls, '\0');
  if (!lu_str2num(ls->buff.b, ls->buff.n - 1, &v))
    lex_error(ls, "malformed number", TK_FLT);
  if (ttisint(&v)) { seminfo->i = ivalue(&v); return TK_INT; }
  seminfo->r = fltvalue(&v);
  return TK_FLT;
}

/* count '=' in a long-bracket opener; returns level or -1 */
static size_t skip_sep(LexState *ls) {
  size_t count = 0;
  int s = ls->current;
  save_and_next(ls);
  while (ls->current == '=') { save_and_next(ls); count++; }
  return (ls->current == s) ? count + 2 : (count == 0) ? 1 : 0;
}

static void read_long_string(LexState *ls, SemInfo *seminfo, size_t sep) {
  int line = ls->linenumber;
  save_and_next(ls);   /* skip second bracket */
  if (currIsNewline(ls)) inclinenumber(ls);
  for (;;) {
    switch (ls->current) {
      case EOZ: {
        const char *what = seminfo ? "string" : "comment";
        const char *msg = strdata(lu_strfmt(ls->L,
            "unfinished long %s (starting at line %d)", what, line));
        lex_error(ls, msg, TK_EOS);
        break;
      }
      case ']': {
        if (skip_sep(ls) == sep) { save_and_next(ls); goto endloop; }
        break;
      }
      case '\n': case '\r': { save(ls, '\n'); inclinenumber(ls); break; }
      default: {
        if (seminfo) save_and_next(ls); else nextc(ls);
      }
    }
  }
 endloop:
  if (seminfo)
    seminfo->ts = lu_newlstr(ls->L, ls->buff.b + sep, ls->buff.n - 2 * sep);
}

static void esccheck(LexState *ls, int c, const char *msg) {
  if (!c) {
    if (ls->current != EOZ) save_and_next(ls);
    lex_error(ls, msg, TK_STRING);
  }
}

static int gethexa(LexState *ls) {
  save_and_next(ls);
  esccheck(ls, isxdigit(ls->current), "hexadecimal digit expected");
  if (isdigit(ls->current)) return ls->current - '0';
  return tolower(ls->current) - 'a' + 10;
}

static int readhexaesc(LexState *ls) {
  int r = gethexa(ls);
  r = (r << 4) + gethexa(ls);
  ls->buff.n -= 2;   /* remove the saved digits */
  return r;
}

static unsigned long readutf8esc(LexState *ls) {
  unsigned long r;
  int i = 4;
  save_and_next(ls);   /* skip 'u' */
  esccheck(ls, ls->current == '{', "missing '{'");
  r = (unsigned long)gethexa(ls);
  for (;;) {
    save_and_next(ls);
    if (!isxdigit(ls->current)) break;
    i++;
    esccheck(ls, r <= (0x7FFFFFFFu >> 4), "UTF-8 value too large");
    r = (r << 4) + (unsigned long)(isdigit(ls->current) ? ls->current - '0'
                                  : tolower(ls->current) - 'a' + 10);
  }
  esccheck(ls, ls->current == '}', "missing '}'");
  nextc(ls);
  ls->buff.n -= (size_t)i;
  return r;
}

int lu_utf8esc(char *buff, unsigned long x) {
  int n = 1;
  if (x < 0x80) buff[7] = (char)x;
  else {
    unsigned int mfb = 0x3f;
    do {
      buff[8 - (n++)] = (char)(0x80 | (x & 0x3f));
      x >>= 6;
      mfb >>= 1;
    } while (x > mfb);
    buff[8 - n] = (char)((~mfb << 1) | x);
  }
  return n;
}

static void utf8esc(LexState *ls) {
  char buff[8];
  int n;
  unsigned long r = readutf8esc(ls);
  n = lu_utf8esc(buff, r);
  {
    int i;
    for (i = 0; i < n; i++) save(ls, buff[8 - n + i]);
  }
}

static int readdecesc(LexState *ls) {
  int i, r = 0;
  for (i = 0; i < 3 && isdigit(ls->current); i++) {
    r = 10 * r + ls->current - '0';
    save_and_next(ls);
  }
  esccheck(ls, r <= 255, "decimal escape too large");
  ls->buff.n -= (size_t)i;
  return r;
}

static void read_string(LexState *ls, int del, SemInfo *seminfo) {
  save_and_next(ls);
  while (ls->current != del) {
    switch (ls->current) {
      case EOZ: lex_error(ls, "unfinished string", TK_EOS); break;
      case '\n': case '\r': lex_error(ls, "unfinished string", TK_STRING); break;
      case '\\': {
        int c;
        save_and_next(ls);
        switch (ls->current) {
          case 'a': c = '\a'; goto read_save;
          case 'b': c = '\b'; goto read_save;
          case 'f': c = '\f'; goto read_save;
          case 'n': c = '\n'; goto read_save;
          case 'r': c = '\r'; goto read_save;
          case 't': c = '\t'; goto read_save;
          case 'v': c = '\v'; goto read_save;
          case 'x': c = readhexaesc(ls); goto read_save;
          case 'u': utf8esc(ls); goto no_save;
          case '\n': case '\r':
            inclinenumber(ls); c = '\n'; goto only_save;
          case '\\': case '\"': case '\'': c = ls->current; goto read_save;
          case EOZ: goto no_save;
          case 'z': {
            ls->buff.n--;   /* remove '\\' */
            nextc(ls);
            while (isspace(ls->current)) {
              if (currIsNewline(ls)) inclinenumber(ls); else nextc(ls);
            }
            goto no_save;
          }
          default: {
            esccheck(ls, 0, "invalid escape sequence");
            c = 0; goto no_save;
          }
        }
       read_save:
        nextc(ls);
       only_save:
        ls->buff.n--;   /* remove '\\' */
        save(ls, c);
       no_save:
        break;
      }
      default: save_and_next(ls);
    }
  }
  save_and_next(ls);   /* skip delimiter */
  seminfo->ts = lu_newlstr(ls->L, ls->buff.b + 1, ls->buff.n - 2);
}

static int llex(LexState *ls, SemInfo *seminfo) {
  ls->buff.n = 0;
  for (;;) {
    switch (ls->current) {
      case '\n': case '\r': inclinenumber(ls); break;
      case ' ': case '\f': case '\t': case '\v': nextc(ls); break;
      case '-': {
        nextc(ls);
        if (ls->current != '-') return '-';
        nextc(ls);
        if (ls->current == '[') {
          size_t sep = skip_sep(ls);
          ls->buff.n = 0;
          if (sep >= 2) { read_long_string(ls, NULL, sep); ls->buff.n = 0; break; }
        }
        while (!currIsNewline(ls) && ls->current != EOZ) nextc(ls);
        break;
      }
      case '[': {
        size_t sep = skip_sep(ls);
        if (sep >= 2) { read_long_string(ls, seminfo, sep); return TK_STRING; }
        else if (sep == 0) lex_error(ls, "invalid long string delimiter", TK_STRING);
        return '[';
      }
      case '=': nextc(ls); if (check_next1(ls, '=')) return TK_EQ; return '=';
      case '<': nextc(ls);
        if (check_next1(ls, '=')) return TK_LE;
        else if (check_next1(ls, '<')) return TK_SHL;
        return '<';
      case '>': nextc(ls);
        if (check_next1(ls, '=')) return TK_GE;
        else if (check_next1(ls, '>')) return TK_SHR;
        return '>';
      case '/': nextc(ls); if (check_next1(ls, '/')) return TK_IDIV; return '/';
      case '~': nextc(ls); if (check_next1(ls, '=')) return TK_NE; return '~';
      case ':': nextc(ls); if (check_next1(ls, ':')) return TK_DBCOLON; return ':';
      case '"': case '\'': read_string(ls, ls->current, seminfo); return TK_STRING;
      case '.': {
        save_and_next(ls);
        if (check_next1(ls, '.')) {
          if (check_next1(ls, '.')) return TK_DOTS;
          return TK_CONCAT;
        }
        if (!isdigit(ls->current)) return '.';
        return read_numeral(ls, seminfo);
      }
      case '0': case '1': case '2': case '3': case '4':
      case '5': case '6': case '7': case '8': case '9':
        return read_numeral(ls, seminfo);
      case EOZ: return TK_EOS;
      default: {
        if (isalpha(ls->current) || ls->current == '_') {
          Str *ts;
          do { save_and_next(ls); } while (isalnum(ls->current) || ls->current == '_');
          ts = lu_newlstr(ls->L, ls->buff.b, ls->buff.n);
          seminfo->ts = ts;
          if (ts->reserved > 0) return (int)ts->reserved - 1 + TK_FIRST;
          return TK_NAME;
        } else {
          int c = ls->current;
          nextc(ls);
          return c;
        }
      }
    }
  }
}

void lex_next(LexState *ls) {
  ls->lastline = ls->linenumber;
  if (ls->lookahead.token != TK_EOS) {
    ls->t = ls->lookahead;
    ls->lookahead.token = TK_EOS;
  } else {
    ls->t.token = llex(ls, &ls->t.seminfo);
    ls->t.line = ls->linenumber;
  }
}

int lex_lookahead(LexState *ls) {
  ls->lookahead.token = llex(ls, &ls->lookahead.seminfo);
  ls->lookahead.line = ls->linenumber;
  return ls->lookahead.token;
}

void lex_init(lua_State *L) {
  int i;
  for (i = 0; i < NUM_RESERVED; i++) {
    Str *s = lu_newstr(L, lex_tokens[i]);
    s->reserved = (uint32_t)(i + 1);
    /* keep reserved words alive forever */
    L->G->fixed[L->G->nfixed++] = mkgc(T_STR, s);
  }
}

