#ifndef lex_h
#define lex_h

#include "lu.h"

enum RESERVED {
  TK_FIRST = 257,
  TK_AND = TK_FIRST, TK_BREAK, TK_DO, TK_ELSE, TK_ELSEIF, TK_END, TK_FALSE,
  TK_FOR, TK_FUNCTION, TK_GOTO, TK_IF, TK_IN, TK_LOCAL, TK_NIL, TK_NOT,
  TK_OR, TK_REPEAT, TK_RETURN, TK_THEN, TK_TRUE, TK_UNTIL, TK_WHILE,
  /* other terminal symbols */
  TK_IDIV, TK_CONCAT, TK_DOTS, TK_EQ, TK_GE, TK_LE, TK_NE, TK_SHL, TK_SHR,
  TK_DBCOLON, TK_EOS, TK_FLT, TK_INT, TK_NAME, TK_STRING
};

#define NUM_RESERVED  (TK_WHILE - TK_FIRST + 1)

typedef union {
  lu_Number r;
  lu_Integer i;
  Str *ts;
} SemInfo;

typedef struct Token {
  int token;
  int line;
  SemInfo seminfo;
} Token;

typedef struct LexState {
  int current;
  int linenumber;
  int lastline;
  Token t;
  Token lookahead;
  struct FuncState *fs;
  lua_State *L;
  const char *p, *pend;
  Buf buff;
  struct Dyndata *dyd;
  Str *source;
} LexState;

extern const char *const lex_tokens[];

void lex_init(lua_State *L);
void lex_setinput(lua_State *L, LexState *ls, const char *buf, size_t len, Str *source);
void lex_next(LexState *ls);
int  lex_lookahead(LexState *ls);
void lex_error(LexState *ls, const char *msg, int token);
void lex_syntaxerror(LexState *ls, const char *msg);
const char *lex_token2str(LexState *ls, int token);
int lu_utf8esc(char *buff, unsigned long x);

#endif

