#ifndef code_h
#define code_h

#include "lu.h"

/* opcodes */
enum OpCode {
  OP_MOVE,      /* A B      R[A] := R[B] */
  OP_LOADK,     /* A B      R[A] := K[B] */
  OP_LOADNIL,   /* A B      R[A..A+B] := nil */
  OP_LOADBOOL,  /* A B      R[A] := (B != 0) */
  OP_LOADINT,   /* A B      R[A] := (integer)B */
  OP_GETUPV,    /* A B      R[A] := U[B] */
  OP_SETUPV,    /* A B      U[B] := R[A] */
  OP_GETTABUP,  /* A B C    R[A] := U[B][RK(C)] */
  OP_SETTABUP,  /* A B C    U[A][RK(B)] := RK(C) */
  OP_GETTAB,    /* A B C    R[A] := R[B][RK(C)] */
  OP_SETTAB,    /* A B C    R[A][RK(B)] := RK(C) */
  OP_NEWTAB,    /* A B C    R[A] := {} */
  OP_SELF,      /* A B C    R[A+1] := R[B]; R[A] := R[B][RK(C)] */
  OP_ADD, OP_SUB, OP_MUL, OP_MOD, OP_POW, OP_DIV, OP_IDIV,
  OP_BAND, OP_BOR, OP_BXOR, OP_SHL, OP_SHR,
  OP_UNM, OP_BNOT, OP_NOT, OP_LEN,
  OP_CONCAT,    /* A B C    R[A] := R[B].. ... ..R[C] */
  OP_JMP,       /* A B      pc += B; if A>0 close level A-1 */
  OP_EQ,        /* A B C    if (RK(B)==RK(C)) != A then pc++ */
  OP_LT, OP_LE,
  OP_TEST,      /* A C      if truthy(R[A]) != C then pc++ */
  OP_TESTSET,   /* A B C    if truthy(R[B]) == C then R[A]:=R[B] else pc++ */
  OP_CALL,      /* A B C    call R[A] with B-1 args, C-1 results */
  OP_TAILCALL,  /* A B      */
  OP_RETURN,    /* A B      return R[A..A+B-2] */
  OP_FORPREP,   /* A B      */
  OP_FORLOOP,   /* A B      */
  OP_TFORPREP,  /* A B      */
  OP_TFORCALL,  /* A C      */
  OP_TFORLOOP,  /* A B      */
  OP_SETLIST,   /* A B C    R[A][C+i] := R[A+i] */
  OP_CLOSURE,   /* A B      R[A] := closure(P[B]) */
  OP_VARARG,    /* A B      R[A..A+B-2] := ... */
  OP_CLOSE,     /* A        close upvalues/tbc >= A */
  OP_TBC,       /* A        mark R[A] to be closed */
  OP_NOP,
  NUM_OPS
};

#define NO_JUMP (-1)

/* expression descriptors */
typedef enum {
  VVOID, VNIL, VTRUE, VFALSE, VKINT, VKFLT, VKSTR, VK,
  VNONRELOC, VLOCAL, VUPVAL, VINDEXED, VINDEXUP,
  VJMP, VRELOC, VCALL, VVARARG
} expkind;

typedef struct expdesc {
  expkind k;
  union {
    lu_Integer ival;
    lu_Number nval;
    Str *strval;
    int info;
    struct { int t; int idx; int isk; } ind;
  } u;
  int t, f;
  int vidx;
  uint8_t nkind;      /* HN_* */
  Str *nname;
} expdesc;

/* variable kinds */
#define VDKREG    0
#define RDKCONST  1
#define RDKTOCLOSE 2
#define RDKCTC    3

typedef struct Vardesc {
  uint8_t kind;
  int ridx;
  int pidx;
  Str *name;
  Value k;
} Vardesc;

typedef struct Labeldesc {
  Str *name;
  int pc;
  int line;
  int nactvar;
} Labeldesc;

typedef struct Dyndata {
  Vardesc *actvar; int nactvar, cactvar;
  Labeldesc *gt; int ngt, cgt;
  Labeldesc *label; int nlabel, clabel;
} Dyndata;

typedef struct BlockCnt {
  struct BlockCnt *prev;
  int firstlabel;
  int firstgoto;
  int nactvar;
  uint8_t upval;
  uint8_t isloop;
  uint8_t insidetbc;
} BlockCnt;

typedef struct FuncState {
  Proto *f;
  struct FuncState *prev;
  struct LexState *ls;
  BlockCnt *bl;
  int pc;
  int lasttarget;
  int previousline;
  int firstlocal;
  int firstlabel;
  int nactvar;
  int freereg;
  int needclose;
  int codecap, kcap, pcap, locvarcap, upvalcap, hintcap;
} FuncState;

#endif

