/*
** parse.c -- single pass parser and code generator
*/
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include "lu.h"
#include "lex.h"
#include "code.h"

#define hasjumps(e)  ((e)->t != (e)->f)

static void expr(LexState *ls, expdesc *v);
static void statement(LexState *ls);
static void statlist(LexState *ls);
static int  cond(LexState *ls);
static void exp2nextreg(FuncState *fs, expdesc *e);
static int  exp2anyreg(FuncState *fs, expdesc *e);
static void exp2val(FuncState *fs, expdesc *e);
static void dischargevars(FuncState *fs, expdesc *e);
static void patchtohere(FuncState *fs, int list);
static void patchlist(FuncState *fs, int list, int target);
static void concatjump(FuncState *fs, int *l1, int l2);
static int  jump(FuncState *fs);
static void gotostat(LexState *ls, int line, Str *name);

/* ------------------------------------------------------------- diagnostics */

static void errorlimit(FuncState *fs, int limit, const char *what) {
  lua_State *L = fs->ls->L;
  int line = fs->f->linedefined;
  const char *where = (line == 0) ? "main function"
                    : strdata(lu_strfmt(L, "function at line %d", line));
  lex_syntaxerror(fs->ls,
     strdata(lu_strfmt(L, "too many %s (limit is %d) in %s", what, limit, where)));
}

static void checklimit(FuncState *fs, int v, int l, const char *what) {
  if (v > l) errorlimit(fs, l, what);
}

static void error_expected(LexState *ls, int token) {
  lex_syntaxerror(ls,
     strdata(lu_strfmt(ls->L, "%s expected", lex_token2str(ls, token))));
}

static int testnext(LexState *ls, int c) {
  if (ls->t.token == c) { lex_next(ls); return 1; }
  return 0;
}

static void check(LexState *ls, int c) {
  if (ls->t.token != c) error_expected(ls, c);
}

static void checknext(LexState *ls, int c) { check(ls, c); lex_next(ls); }

#define check_condition(ls,c,msg) { if (!(c)) lex_syntaxerror(ls, msg); }

static void check_match(LexState *ls, int what, int who, int where) {
  if (!testnext(ls, what)) {
    if (where == ls->linenumber) error_expected(ls, what);
    else
      lex_syntaxerror(ls, strdata(lu_strfmt(ls->L,
          "%s expected (to close %s at line %d)",
          lex_token2str(ls, what), lex_token2str(ls, who), where)));
  }
}

static Str *str_checkname(LexState *ls) {
  Str *ts;
  check(ls, TK_NAME);
  ts = ls->t.seminfo.ts;
  lex_next(ls);
  return ts;
}

/* -------------------------------------------------------------- code emit */

static int emit(FuncState *fs, int op, int a, int b, int c) {
  Proto *f = fs->f;
  f->code = (Instr *)lu_growvec(fs->ls->L, f->code, &fs->codecap, fs->pc + 1, sizeof(Instr));
  f->lineinfo = (int *)lu_realloc(fs->ls->L, f->lineinfo,
      (size_t)(fs->pc) * sizeof(int), (size_t)(fs->pc + 1) * sizeof(int));
  f->code[fs->pc].op = (uint8_t)op;
  f->code[fs->pc].a = (uint8_t)a;
  f->code[fs->pc].b = b;
  f->code[fs->pc].c = c;
  f->lineinfo[fs->pc] = fs->ls->lastline;
  return fs->pc++;
}

static void fixline(FuncState *fs, int pc, int line) { fs->f->lineinfo[pc] = line; }

static void addhint(FuncState *fs, int pc, int slot, expdesc *e) {
  Proto *f = fs->f;
  if (e == NULL || e->nkind == HN_NONE || e->nname == NULL) return;
  f->hints = (NameHint *)lu_growvec(fs->ls->L, f->hints, &fs->hintcap, f->nhints + 1,
                                    sizeof(NameHint));
  f->hints[f->nhints].pc = pc;
  f->hints[f->nhints].slot = (uint8_t)slot;
  f->hints[f->nhints].kind = e->nkind;
  f->hints[f->nhints].name = e->nname;
  f->nhints++;
}

static void addhint_raw(FuncState *fs, int pc, int slot, int kind, Str *name) {
  Proto *f = fs->f;
  if (name == NULL) return;
  f->hints = (NameHint *)lu_growvec(fs->ls->L, f->hints, &fs->hintcap, f->nhints + 1,
                                    sizeof(NameHint));
  f->hints[f->nhints].pc = pc;
  f->hints[f->nhints].slot = (uint8_t)slot;
  f->hints[f->nhints].kind = (uint8_t)kind;
  f->hints[f->nhints].name = name;
  f->nhints++;
}

static int addk(FuncState *fs, Value v) {
  Proto *f = fs->f;
  int i;
  for (i = 0; i < f->nk; i++) {
    Value *o = &f->k[i];
    if (o->tt == v.tt) {
      switch (v.tt) {
        case T_NIL: return i;
        case T_BOOL: if (o->u.i == v.u.i) return i; break;
        case T_INT: if (o->u.i == v.u.i) return i; break;
        case T_FLT: {
          /* distinguish 0.0 from -0.0 */
          if (memcmp(&o->u.n, &v.u.n, sizeof(lu_Number)) == 0) return i;
          break;
        }
        case T_STR: if (gcvalue(o) == gcvalue(&v)) return i; break;
        default: break;
      }
    }
  }
  f->k = (Value *)lu_growvec(fs->ls->L, f->k, &fs->kcap, f->nk + 1, sizeof(Value));
  f->k[f->nk] = v;
  return f->nk++;
}

static int stringK(FuncState *fs, Str *s) { return addk(fs, mkgc(T_STR, s)); }
static int intK(FuncState *fs, lu_Integer i) { return addk(fs, mkint(i)); }
static int fltK(FuncState *fs, lu_Number n) { return addk(fs, mkflt(n)); }

static void checkstack(FuncState *fs, int n) {
  int newstack = fs->freereg + n;
  if (newstack > fs->f->maxstack) {
    if (newstack >= MAXREGS)
      errorlimit(fs, MAXREGS, "registers");
    fs->f->maxstack = newstack;
  }
}

static void reserveregs(FuncState *fs, int n) {
  checkstack(fs, n);
  fs->freereg += n;
}

static void freereg(FuncState *fs, int reg) {
  if (reg >= fs->nactvar) {
    fs->freereg--;
  }
}

static void freeexp(FuncState *fs, expdesc *e) {
  if (e->k == VNONRELOC) freereg(fs, e->u.info);
}

static void freeexps(FuncState *fs, expdesc *e1, expdesc *e2) {
  int r1 = (e1->k == VNONRELOC) ? e1->u.info : -1;
  int r2 = (e2->k == VNONRELOC) ? e2->u.info : -1;
  if (r1 > r2) { freereg(fs, r1); if (r2 >= 0) freereg(fs, r2); }
  else { if (r2 >= 0) freereg(fs, r2); if (r1 >= 0) freereg(fs, r1); }
}

/* --------------------------------------------------------------- jumps */

static int getjump(FuncState *fs, int pc) {
  int offset = fs->f->code[pc].b;
  if (offset == NO_JUMP) return NO_JUMP;
  return (pc + 1) + offset;
}

static void fixjump(FuncState *fs, int pc, int dest) {
  fs->f->code[pc].b = dest - (pc + 1);
}

static int jump(FuncState *fs) {
  return emit(fs, OP_JMP, 0, NO_JUMP, 0);
}

static void concatjump(FuncState *fs, int *l1, int l2) {
  if (l2 == NO_JUMP) return;
  if (*l1 == NO_JUMP) { *l1 = l2; return; }
  {
    int list = *l1, next;
    while ((next = getjump(fs, list)) != NO_JUMP) list = next;
    fixjump(fs, list, l2);
  }
}

static int getlabel(FuncState *fs) { fs->lasttarget = fs->pc; return fs->pc; }

/* instruction that controls a test-jump pair, or NULL */
static Instr *getjumpcontrol(FuncState *fs, int pc) {
  Instr *pi = &fs->f->code[pc];
  if (pc >= 1) {
    Instr *prev = pi - 1;
    if (prev->op == OP_EQ || prev->op == OP_LT || prev->op == OP_LE ||
        prev->op == OP_TEST || prev->op == OP_TESTSET)
      return prev;
  }
  return pi;
}

static int patchtestreg(FuncState *fs, int node, int reg) {
  Instr *i = getjumpcontrol(fs, node);
  if (i->op != OP_TESTSET) return 0;
  if (reg != -1 && reg != i->b) i->a = (uint8_t)reg;
  else { i->op = OP_TEST; i->a = (uint8_t)i->b; i->b = 0; }
  return 1;
}

static void removevalues(FuncState *fs, int list) {
  for (; list != NO_JUMP; list = getjump(fs, list)) patchtestreg(fs, list, -1);
}

static void patchlistaux(FuncState *fs, int list, int vtarget, int reg, int dtarget) {
  while (list != NO_JUMP) {
    int next = getjump(fs, list);
    if (patchtestreg(fs, list, reg)) fixjump(fs, list, vtarget);
    else fixjump(fs, list, dtarget);
    list = next;
  }
}

static void patchlist(FuncState *fs, int list, int target) {
  patchlistaux(fs, list, target, -1, target);
}

static void patchtohere(FuncState *fs, int list) {
  int hr = getlabel(fs);
  patchlist(fs, list, hr);
}

/* mark a jump list so it closes upvalues at `level` */
static void patchclose(FuncState *fs, int list, int level) {
  for (; list != NO_JUMP; list = getjump(fs, list)) {
    if (fs->f->code[list].op == OP_JMP && fs->f->code[list].a <= level)
      fs->f->code[list].a = (uint8_t)(level + 1);
  }
}

/* ------------------------------------------------------- expression codegen */

static void nil2reg(FuncState *fs, int from, int n) {
  if (fs->pc > fs->lasttarget) {
    Instr *prev = &fs->f->code[fs->pc - 1];
    if (prev->op == OP_LOADNIL) {
      int pfrom = prev->a, pl = pfrom + prev->b;
      if ((pfrom <= from && from <= pl + 1) || (from <= pfrom && pfrom <= from + n)) {
        int nfrom = (pfrom < from) ? pfrom : from;
        int nto = ((pl > from + n - 1) ? pl : from + n - 1);
        prev->a = (uint8_t)nfrom;
        prev->b = nto - nfrom;
        return;
      }
    }
  }
  emit(fs, OP_LOADNIL, from, n - 1, 0);
}

static void dischargetoreg(FuncState *fs, expdesc *e, int reg) {
  dischargevars(fs, e);
  switch (e->k) {
    case VNIL: nil2reg(fs, reg, 1); break;
    case VFALSE: emit(fs, OP_LOADBOOL, reg, 0, 0); break;
    case VTRUE: emit(fs, OP_LOADBOOL, reg, 1, 0); break;
    case VKSTR: emit(fs, OP_LOADK, reg, stringK(fs, e->u.strval), 0); break;
    case VK: emit(fs, OP_LOADK, reg, e->u.info, 0); break;
    case VKFLT: emit(fs, OP_LOADK, reg, fltK(fs, e->u.nval), 0); break;
    case VKINT: {
      if (e->u.ival >= INT32_MIN && e->u.ival <= INT32_MAX)
        emit(fs, OP_LOADINT, reg, (int)e->u.ival, 0);
      else
        emit(fs, OP_LOADK, reg, intK(fs, e->u.ival), 0);
      break;
    }
    case VRELOC: fs->f->code[e->u.info].a = (uint8_t)reg; break;
    case VNONRELOC: if (reg != e->u.info) emit(fs, OP_MOVE, reg, e->u.info, 0); break;
    default: return;   /* VJMP, VVOID */
  }
  e->u.info = reg;
  e->k = VNONRELOC;
}

static void discharge2anyreg(FuncState *fs, expdesc *e) {
  if (e->k != VNONRELOC) { reserveregs(fs, 1); dischargetoreg(fs, e, fs->freereg - 1); }
}

static int need_value(FuncState *fs, int list) {
  for (; list != NO_JUMP; list = getjump(fs, list))
    if (getjumpcontrol(fs, list)->op != OP_TESTSET) return 1;
  return 0;
}

static int code_loadbool(FuncState *fs, int A, int b, int jmp) {
  getlabel(fs);
  return emit(fs, OP_LOADBOOL, A, b, jmp);
}

static void exp2reg(FuncState *fs, expdesc *e, int reg) {
  dischargetoreg(fs, e, reg);
  if (e->k == VJMP) concatjump(fs, &e->t, e->u.info);
  if (hasjumps(e)) {
    int final;
    int p_f = NO_JUMP, p_t = NO_JUMP;
    if (need_value(fs, e->t) || need_value(fs, e->f)) {
      int fj = (e->k == VJMP) ? NO_JUMP : jump(fs);
      p_f = code_loadbool(fs, reg, 0, 1);
      p_t = code_loadbool(fs, reg, 1, 0);
      patchtohere(fs, fj);
    }
    final = getlabel(fs);
    patchlistaux(fs, e->f, final, reg, p_f);
    patchlistaux(fs, e->t, final, reg, p_t);
  }
  e->f = e->t = NO_JUMP;
  e->u.info = reg;
  e->k = VNONRELOC;
}

static void exp2nextreg(FuncState *fs, expdesc *e) {
  dischargevars(fs, e);
  freeexp(fs, e);
  reserveregs(fs, 1);
  exp2reg(fs, e, fs->freereg - 1);
}

static int exp2anyreg(FuncState *fs, expdesc *e) {
  dischargevars(fs, e);
  if (e->k == VNONRELOC) {
    if (!hasjumps(e)) return e->u.info;
    if (e->u.info >= fs->nactvar) { exp2reg(fs, e, e->u.info); return e->u.info; }
  }
  exp2nextreg(fs, e);
  return e->u.info;
}

static void exp2anyregup(FuncState *fs, expdesc *e) {
  if (e->k != VUPVAL || hasjumps(e)) exp2anyreg(fs, e);
}

static void exp2val(FuncState *fs, expdesc *e) {
  if (hasjumps(e)) exp2anyreg(fs, e);
  else dischargevars(fs, e);
}

/* encode an operand: register (>=0) or constant (-idx-1) */
static int exp2rk(FuncState *fs, expdesc *e) {
  exp2val(fs, e);
  switch (e->k) {
    case VNIL: if (!hasjumps(e)) return -addk(fs, mknil()) - 1; break;
    case VTRUE: if (!hasjumps(e)) return -addk(fs, mkbool(1)) - 1; break;
    case VFALSE: if (!hasjumps(e)) return -addk(fs, mkbool(0)) - 1; break;
    case VKINT: if (!hasjumps(e)) return -intK(fs, e->u.ival) - 1; break;
    case VKFLT: if (!hasjumps(e)) return -fltK(fs, e->u.nval) - 1; break;
    case VKSTR: if (!hasjumps(e)) return -stringK(fs, e->u.strval) - 1; break;
    case VK: if (!hasjumps(e)) return -e->u.info - 1; break;
    default: break;
  }
  return exp2anyreg(fs, e);
}

static void dischargevars(FuncState *fs, expdesc *e) {
  switch (e->k) {
    case VLOCAL: e->k = VNONRELOC; break;
    case VUPVAL: {
      int pc = emit(fs, OP_GETUPV, 0, e->u.info, 0);
      e->u.info = pc; e->k = VRELOC;
      break;
    }
    case VINDEXUP: {
      int pc = emit(fs, OP_GETTABUP, 0, e->u.ind.t, e->u.ind.idx);
      addhint_raw(fs, pc, 2, HN_NONE, NULL);
      e->u.info = pc; e->k = VRELOC;
      break;
    }
    case VINDEXED: {
      int pc;
      freereg(fs, e->u.ind.t);
      if (e->u.ind.idx >= 0) freereg(fs, e->u.ind.idx);
      pc = emit(fs, OP_GETTAB, 0, e->u.ind.t, e->u.ind.idx);
      e->u.info = pc; e->k = VRELOC;
      break;
    }
    case VVARARG: {
      fs->f->code[e->u.info].b = 2;
      e->k = VRELOC;
      break;
    }
    case VCALL: {
      fs->f->code[e->u.info].c = 2;
      e->k = VRELOC;
      break;
    }
    default: break;
  }
}

static void setoneret(FuncState *fs, expdesc *e) {
  if (e->k == VCALL) { e->k = VNONRELOC; e->u.info = fs->f->code[e->u.info].a; }
  else if (e->k == VVARARG) { fs->f->code[e->u.info].b = 2; e->k = VRELOC; }
}

static void setreturns(FuncState *fs, expdesc *e, int nresults) {
  if (e->k == VCALL) fs->f->code[e->u.info].c = nresults + 1;
  else if (e->k == VVARARG) {
    fs->f->code[e->u.info].b = nresults + 1;
    fs->f->code[e->u.info].a = (uint8_t)fs->freereg;
    reserveregs(fs, 1);
  }
}

static void storevar(FuncState *fs, expdesc *var, expdesc *ex) {
  switch (var->k) {
    case VLOCAL: { freeexp(fs, ex); exp2reg(fs, ex, var->u.info); return; }
    case VUPVAL: { int e = exp2anyreg(fs, ex); emit(fs, OP_SETUPV, e, var->u.info, 0); break; }
    case VINDEXUP: {
      int e = exp2rk(fs, ex);
      int pc = emit(fs, OP_SETTABUP, var->u.ind.t, var->u.ind.idx, e);
      (void)pc;
      break;
    }
    case VINDEXED: {
      int e = exp2rk(fs, ex);
      int pc = emit(fs, OP_SETTAB, var->u.ind.t, var->u.ind.idx, e);
      addhint_raw(fs, pc, 0, var->nkind, var->nname);
      break;
    }
    default: break;
  }
  freeexp(fs, ex);
}

static void codenot(FuncState *fs, expdesc *e) {
  dischargevars(fs, e);
  switch (e->k) {
    case VNIL: case VFALSE: e->k = VTRUE; break;
    case VK: case VKFLT: case VKINT: case VKSTR: case VTRUE: e->k = VFALSE; break;
    case VJMP: {
      Instr *ci = getjumpcontrol(fs, e->u.info);
      if (ci->op == OP_EQ || ci->op == OP_LT || ci->op == OP_LE ||
          ci->op == OP_TEST || ci->op == OP_TESTSET)
        ci->a = (uint8_t)!ci->a;
      break;
    }
    case VRELOC: case VNONRELOC: {
      discharge2anyreg(fs, e);
      freeexp(fs, e);
      e->u.info = emit(fs, OP_NOT, 0, e->u.info, 0);
      e->k = VRELOC;
      break;
    }
    default: break;
  }
  { int tmp = e->f; e->f = e->t; e->t = tmp; }
  removevalues(fs, e->f);
  removevalues(fs, e->t);
}

static void indexed(FuncState *fs, expdesc *t, expdesc *k) {
  uint8_t nk = t->nkind; Str *nn = t->nname;
  if (t->k == VUPVAL) {
    int ti = t->u.info;
    t->u.ind.t = ti;
    t->u.ind.idx = exp2rk(fs, k);
    t->k = VINDEXUP;
  } else {
    t->u.ind.t = exp2anyreg(fs, t);
    t->u.ind.idx = exp2rk(fs, k);
    t->k = VINDEXED;
  }
  t->nkind = nk; t->nname = nn;
}

/* --------------------------------------------------------- constant folding */

static int tonumeral(const expdesc *e, Value *v) {
  if (e->t != NO_JUMP || e->f != NO_JUMP) return 0;
  switch (e->k) {
    case VKINT: if (v) *v = mkint(e->u.ival); return 1;
    case VKFLT: if (v) *v = mkflt(e->u.nval); return 1;
    default: return 0;
  }
}

static int validop(int op, Value *v1, Value *v2) {
  switch (op) {
    case AR_BAND: case AR_BOR: case AR_BXOR: case AR_SHL: case AR_SHR:
    case AR_BNOT: {
      lu_Integer i;
      return lu_tointeger_strict(v1, &i) && lu_tointeger_strict(v2, &i);
    }
    case AR_DIV: case AR_IDIV: case AR_MOD:
      return !(ttisint(v2) && ivalue(v2) == 0);
    default: return 1;
  }
}

static int constfolding(FuncState *fs, int op, expdesc *e1, expdesc *e2) {
  Value v1, v2, res;
  if (!tonumeral(e1, &v1) || !tonumeral(e2, &v2) || !validop(op, &v1, &v2))
    return 0;
  lu_arith(fs->ls->L, op, &v1, &v2, &res);
  if (ttisint(&res)) { e1->k = VKINT; e1->u.ival = ivalue(&res); }
  else {
    lu_Number n = fltvalue(&res);
    if (n != n || n == 0) return 0;
    e1->k = VKFLT; e1->u.nval = n;
  }
  return 1;
}

static const uint8_t binop2op[] = {
  OP_ADD, OP_SUB, OP_MUL, OP_MOD, OP_POW, OP_DIV, OP_IDIV,
  OP_BAND, OP_BOR, OP_BXOR, OP_SHL, OP_SHR
};

static void codearith(FuncState *fs, int op, expdesc *e1, expdesc *e2, int line) {
  int r2, r1, pc;
  uint8_t k1 = e1->nkind, k2 = e2->nkind;
  Str *n1 = e1->nname, *n2 = e2->nname;
  r2 = exp2rk(fs, e2);
  r1 = exp2rk(fs, e1);
  if (r1 >= 0 && r2 >= 0) freeexps(fs, e1, e2);
  else { freeexp(fs, e2); freeexp(fs, e1); }
  pc = emit(fs, binop2op[op], 0, r1, r2);
  e1->u.info = pc;
  e1->k = VRELOC;
  e1->nkind = HN_NONE; e1->nname = NULL;
  if (k1 != HN_NONE) addhint_raw(fs, pc, 1, k1, n1);
  if (k2 != HN_NONE) addhint_raw(fs, pc, 2, k2, n2);
  fixline(fs, pc, line);
}

static void codeunary(FuncState *fs, int op, expdesc *e, int line) {
  int r, pc;
  uint8_t k1 = e->nkind; Str *n1 = e->nname;
  r = exp2anyreg(fs, e);
  freeexp(fs, e);
  pc = emit(fs, op, 0, r, 0);
  e->u.info = pc;
  e->k = VRELOC;
  e->nkind = HN_NONE; e->nname = NULL;
  if (k1 != HN_NONE) addhint_raw(fs, pc, 1, k1, n1);
  fixline(fs, pc, line);
}

static int condjump(FuncState *fs, int op, int a, int b, int c) {
  emit(fs, op, a, b, c);
  return jump(fs);
}

static void codecomp(FuncState *fs, int opr, expdesc *e1, expdesc *e2) {
  int r1, r2;
  int op, cond_ = 1;
  r1 = exp2rk(fs, e1);
  r2 = exp2rk(fs, e2);
  freeexps(fs, e1, e2);
  switch (opr) {
    case 0: op = OP_EQ; cond_ = 1; break;                 /* == */
    case 1: op = OP_EQ; cond_ = 0; break;                 /* ~= */
    case 2: op = OP_LT; cond_ = 1; break;                 /* <  */
    case 3: op = OP_LE; cond_ = 1; break;                 /* <= */
    case 4: { int t = r1; r1 = r2; r2 = t; op = OP_LT; cond_ = 1; break; }  /* > */
    case 5: { int t = r1; r1 = r2; r2 = t; op = OP_LE; cond_ = 1; break; }  /* >= */
    default: op = OP_EQ; break;
  }
  e1->u.info = condjump(fs, op, cond_, r1, r2);
  e1->k = VJMP;
  e1->nkind = HN_NONE; e1->nname = NULL;
}

static void goiftrue(FuncState *fs, expdesc *e);
static void goiffalse(FuncState *fs, expdesc *e);

static int jumponcond(FuncState *fs, expdesc *e, int cond_) {
  if (e->k == VRELOC) {
    Instr *ie = &fs->f->code[e->u.info];
    if (ie->op == OP_NOT) {
      int b = ie->b;
      fs->pc--;    /* remove the NOT */
      fs->f->nhints = fs->f->nhints;  /* hints for NOT are harmless */
      return condjump(fs, OP_TEST, b, 0, !cond_);
    }
  }
  discharge2anyreg(fs, e);
  freeexp(fs, e);
  return condjump(fs, OP_TESTSET, 0, e->u.info, cond_);
}

static void goiftrue(FuncState *fs, expdesc *e) {
  int pc;
  dischargevars(fs, e);
  switch (e->k) {
    case VJMP: { Instr *ci = getjumpcontrol(fs, e->u.info); ci->a = (uint8_t)!ci->a; pc = e->u.info; break; }
    case VK: case VKFLT: case VKINT: case VKSTR: case VTRUE: pc = NO_JUMP; break;
    default: pc = jumponcond(fs, e, 0); break;
  }
  concatjump(fs, &e->f, pc);
  patchtohere(fs, e->t);
  e->t = NO_JUMP;
}

static void goiffalse(FuncState *fs, expdesc *e) {
  int pc;
  dischargevars(fs, e);
  switch (e->k) {
    case VJMP: pc = e->u.info; break;
    case VNIL: case VFALSE: pc = NO_JUMP; break;
    default: pc = jumponcond(fs, e, 1); break;
  }
  concatjump(fs, &e->t, pc);
  patchtohere(fs, e->f);
  e->f = NO_JUMP;
}

/* ------------------------------------------------------------- variables */

static void init_exp(expdesc *e, expkind k, int i) {
  e->f = e->t = NO_JUMP;
  e->k = k;
  e->u.info = i;
  e->nkind = HN_NONE;
  e->nname = NULL;
  e->vidx = -1;
}

static void codestring(expdesc *e, Str *s) {
  e->f = e->t = NO_JUMP;
  e->k = VKSTR;
  e->u.strval = s;
  e->nkind = HN_NONE; e->nname = NULL; e->vidx = -1;
}

static Vardesc *getlocalvardesc(FuncState *fs, int vidx) {
  return &fs->ls->dyd->actvar[fs->firstlocal + vidx];
}

static int reglevel(FuncState *fs, int nvar) {
  while (nvar-- > 0) {
    Vardesc *vd = getlocalvardesc(fs, nvar);
    if (vd->kind != RDKCTC) return vd->ridx + 1;
  }
  return 0;
}

static int luaY_nvarstack(FuncState *fs) { return reglevel(fs, fs->nactvar); }

static LocVar *localdebuginfo(FuncState *fs, int vidx) {
  Vardesc *vd = getlocalvardesc(fs, vidx);
  if (vd->kind == RDKCTC) return NULL;
  return &fs->f->locvars[vd->pidx];
}

static int new_localvar(LexState *ls, Str *name) {
  lua_State *L = ls->L;
  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  Vardesc *var;
  checklimit(fs, dyd->nactvar + 1 - fs->firstlocal, MAXVARS, "local variables");
  if (dyd->nactvar + 1 > dyd->cactvar) {
    int nc = dyd->cactvar ? dyd->cactvar * 2 : 16;
    dyd->actvar = (Vardesc *)lu_realloc(L, dyd->actvar,
        (size_t)dyd->cactvar * sizeof(Vardesc), (size_t)nc * sizeof(Vardesc));
    dyd->cactvar = nc;
  }
  var = &dyd->actvar[dyd->nactvar++];
  var->kind = VDKREG;
  var->name = name;
  var->ridx = 0; var->pidx = 0; var->k = mknil();
  return dyd->nactvar - 1 - fs->firstlocal;
}

static int registerlocalvar(LexState *ls, FuncState *fs, Str *varname) {
  Proto *f = fs->f;
  f->locvars = (LocVar *)lu_growvec(ls->L, f->locvars, &fs->locvarcap,
                                    f->nlocvars + 1, sizeof(LocVar));
  f->locvars[f->nlocvars].name = varname;
  f->locvars[f->nlocvars].startpc = fs->pc;
  f->locvars[f->nlocvars].endpc = 0;
  return f->nlocvars++;
}

static void adjustlocalvars(LexState *ls, int nvars) {
  FuncState *fs = ls->fs;
  int reglvl = luaY_nvarstack(fs);
  int i;
  for (i = 0; i < nvars; i++) {
    int vidx = fs->nactvar++;
    Vardesc *var = getlocalvardesc(fs, vidx);
    var->ridx = reglvl++;
    var->pidx = registerlocalvar(ls, fs, var->name);
  }
}

static void removevars(FuncState *fs, int tolevel) {
  fs->ls->dyd->nactvar -= (fs->nactvar - tolevel);
  while (fs->nactvar > tolevel) {
    LocVar *var = localdebuginfo(fs, --fs->nactvar);
    if (var) var->endpc = fs->pc;
  }
}

static int searchupvalue(FuncState *fs, Str *name) {
  int i;
  for (i = 0; i < fs->f->nupvals; i++)
    if (fs->f->upvals[i].name == name) return i;
  return -1;
}

static UpvalDesc *allocupvalue(FuncState *fs) {
  Proto *f = fs->f;
  checklimit(fs, f->nupvals + 1, MAXUPVAL, "upvalues");
  f->upvals = (UpvalDesc *)lu_growvec(fs->ls->L, f->upvals, &fs->upvalcap,
                                      f->nupvals + 1, sizeof(UpvalDesc));
  return &f->upvals[f->nupvals++];
}

static int newupvalue(FuncState *fs, Str *name, expdesc *v) {
  UpvalDesc *up = allocupvalue(fs);
  FuncState *prev = fs->prev;
  if (v->k == VLOCAL) {
    up->instack = 1;
    up->idx = v->u.info;
  } else {
    up->instack = 0;
    up->idx = v->u.info;
  }
  (void)prev;
  up->name = name;
  return fs->f->nupvals - 1;
}

static int searchvar(FuncState *fs, Str *name, expdesc *var) {
  int i;
  for (i = fs->nactvar - 1; i >= 0; i--) {
    Vardesc *vd = getlocalvardesc(fs, i);
    if (vd->name == name) {
      if (vd->kind == RDKCTC) {
        /* compile-time constant */
        var->f = var->t = NO_JUMP;
        var->nkind = HN_NONE; var->nname = NULL; var->vidx = i;
        switch (vd->k.tt) {
          case T_NIL: var->k = VNIL; break;
          case T_BOOL: var->k = bvalue(&vd->k) ? VTRUE : VFALSE; break;
          case T_INT: var->k = VKINT; var->u.ival = ivalue(&vd->k); break;
          case T_FLT: var->k = VKFLT; var->u.nval = fltvalue(&vd->k); break;
          case T_STR: var->k = VKSTR; var->u.strval = strvalue(&vd->k); break;
          default: var->k = VNIL; break;
        }
      } else {
        init_exp(var, VLOCAL, vd->ridx);
        var->vidx = i;
      }
      return var->k;
    }
  }
  return -1;
}

static void markupval(FuncState *fs, int level) {
  BlockCnt *bl = fs->bl;
  while (bl && bl->nactvar > level) bl = bl->prev;
  if (bl) bl->upval = 1;
  fs->needclose = 1;
}

static void singlevaraux(FuncState *fs, Str *n, expdesc *var, int base) {
  if (fs == NULL) { init_exp(var, VVOID, 0); return; }
  {
    int v = searchvar(fs, n, var);
    if (v >= 0) {
      if (v == VLOCAL && !base) markupval(fs, var->vidx);
      return;
    }
    {
      int idx = searchupvalue(fs, n);
      if (idx < 0) {
        singlevaraux(fs->prev, n, var, 0);
        if (var->k == VLOCAL || var->k == VUPVAL) idx = newupvalue(fs, n, var);
        else return;
      }
      init_exp(var, VUPVAL, idx);
    }
  }
}

static void singlevar(LexState *ls, expdesc *var) {
  Str *varname = str_checkname(ls);
  FuncState *fs = ls->fs;
  singlevaraux(fs, varname, var, 1);
  if (var->k == VVOID) {
    expdesc key;
    Str *envn = lu_newstr(ls->L, "_ENV");
    singlevaraux(fs, envn, var, 1);
    codestring(&key, varname);
    indexed(fs, var, &key);
    var->nkind = HN_GLOBAL; var->nname = varname;
  } else if (var->k == VLOCAL) {
    var->nkind = HN_LOCAL; var->nname = varname;
  } else if (var->k == VUPVAL) {
    var->nkind = HN_UPVAL; var->nname = varname;
  } else {
    var->nkind = HN_CONST; var->nname = varname;
  }
}

/* ---------------------------------------------------------------- blocks */

static void enterblock(FuncState *fs, BlockCnt *bl, int isloop) {
  bl->isloop = (uint8_t)isloop;
  bl->nactvar = fs->nactvar;
  bl->firstlabel = fs->ls->dyd->nlabel;
  bl->firstgoto = fs->ls->dyd->ngt;
  bl->upval = 0;
  bl->insidetbc = (uint8_t)(fs->bl != NULL && fs->bl->insidetbc);
  bl->prev = fs->bl;
  fs->bl = bl;
}

static void undefgoto(LexState *ls, Labeldesc *gt) {
  const char *msg;
  if (strcmp(strdata(gt->name), "break") == 0)
    msg = strdata(lu_strfmt(ls->L, "break outside a loop at line %d", gt->line));
  else
    msg = strdata(lu_strfmt(ls->L, "no visible label '%s' for goto at line %d",
                            strdata(gt->name), gt->line));
  lex_syntaxerror(ls, msg);
}

static void removelabels(LexState *ls, int level) { ls->dyd->nlabel = level; }

static int newlabelentry(LexState *ls, int isgoto, Str *name, int line, int pc) {
  Dyndata *dyd = ls->dyd;
  Labeldesc **arr = isgoto ? &dyd->gt : &dyd->label;
  int *n = isgoto ? &dyd->ngt : &dyd->nlabel;
  int *c = isgoto ? &dyd->cgt : &dyd->clabel;
  if (*n + 1 > *c) {
    int nc = *c ? *c * 2 : 8;
    *arr = (Labeldesc *)lu_realloc(ls->L, *arr, (size_t)*c * sizeof(Labeldesc),
                                   (size_t)nc * sizeof(Labeldesc));
    *c = nc;
  }
  (*arr)[*n].name = name;
  (*arr)[*n].line = line;
  (*arr)[*n].nactvar = ls->fs->nactvar;
  (*arr)[*n].pc = pc;
  return (*n)++;
}

static void solvegoto(LexState *ls, int g, Labeldesc *label) {
  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  Labeldesc *gt = &dyd->gt[g];
  patchclose(fs, gt->pc, reglevel(fs, label->nactvar));
  patchlist(fs, gt->pc, label->pc);
  { int i; for (i = g; i < dyd->ngt - 1; i++) dyd->gt[i] = dyd->gt[i + 1]; }
  dyd->ngt--;
}

static Labeldesc *findlabel(LexState *ls, Str *name) {
  int i;
  Dyndata *dyd = ls->dyd;
  FuncState *fs = ls->fs;
  for (i = fs->firstlabel; i < dyd->nlabel; i++)
    if (dyd->label[i].name == name) return &dyd->label[i];
  return NULL;
}

static void solvegotos(LexState *ls, Labeldesc *lb) {
  Dyndata *dyd = ls->dyd;
  int i = ls->fs->bl->firstgoto;
  while (i < dyd->ngt) {
    if (dyd->gt[i].name == lb->name) solvegoto(ls, i, lb);
    else i++;
  }
}

static int createlabel(LexState *ls, Str *name, int line, int last) {
  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  int l = newlabelentry(ls, 0, name, line, getlabel(fs));
  if (last) dyd->label[l].nactvar = fs->bl->nactvar;
  solvegotos(ls, &dyd->label[l]);
  return 0;
}

static void movegotosout(FuncState *fs, BlockCnt *bl) {
  int i;
  Dyndata *dyd = fs->ls->dyd;
  for (i = bl->firstgoto; i < dyd->ngt; i++) {
    Labeldesc *gt = &dyd->gt[i];
    if (reglevel(fs, gt->nactvar) > reglevel(fs, bl->nactvar))
      patchclose(fs, gt->pc, reglevel(fs, bl->nactvar));
    gt->nactvar = bl->nactvar;
  }
}

static void leaveblock(FuncState *fs) {
  BlockCnt *bl = fs->bl;
  LexState *ls = fs->ls;
  int stklevel = reglevel(fs, bl->nactvar);
  removevars(fs, bl->nactvar);
  if (bl->isloop)
    createlabel(ls, lu_newstr(ls->L, "break"), 0, 0);
  if (bl->upval || bl->insidetbc)
    emit(fs, OP_CLOSE, stklevel, 0, 0);
  fs->bl = bl->prev;
  removelabels(ls, bl->firstlabel);
  fs->freereg = stklevel;
  if (bl->prev)
    movegotosout(fs, bl->prev);
  else if (ls->dyd->ngt > bl->firstgoto)
    undefgoto(ls, &ls->dyd->gt[bl->firstgoto]);
}

/* --------------------------------------------------------------- functions */

static void open_func(LexState *ls, FuncState *fs, BlockCnt *bl) {
  Proto *f = fs->f;
  fs->prev = ls->fs;
  fs->ls = ls;
  ls->fs = fs;
  fs->pc = 0;
  fs->lasttarget = 0;
  fs->previousline = f->linedefined;
  fs->nactvar = 0;
  fs->firstlocal = ls->dyd->nactvar;
  fs->firstlabel = ls->dyd->nlabel;
  fs->freereg = 0;
  fs->needclose = 0;
  fs->bl = NULL;
  fs->codecap = fs->kcap = fs->pcap = fs->locvarcap = fs->upvalcap = fs->hintcap = 0;
  f->source = ls->source;
  f->maxstack = 2;
  enterblock(fs, bl, 0);
}

static void close_func(LexState *ls) {
  lua_State *L = ls->L;
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  emit(fs, OP_RETURN, luaY_nvarstack(fs), 1, 0);
  leaveblock(fs);
  f->ncode = fs->pc;
  f->code = (Instr *)lu_realloc(L, f->code, (size_t)fs->codecap * sizeof(Instr),
                                (size_t)fs->pc * sizeof(Instr));
  ls->fs = fs->prev;
}

/* --------------------------------------------------------------- grammar */

static int block_follow(LexState *ls, int withuntil) {
  switch (ls->t.token) {
    case TK_ELSE: case TK_ELSEIF: case TK_END: case TK_EOS: return 1;
    case TK_UNTIL: return withuntil;
    default: return 0;
  }
}

static void block(LexState *ls) {
  FuncState *fs = ls->fs;
  BlockCnt bl;
  enterblock(fs, &bl, 0);
  statlist(ls);
  leaveblock(fs);
}

struct LHS_assign {
  struct LHS_assign *prev;
  expdesc v;
};

static void check_conflict(LexState *ls, struct LHS_assign *lh, expdesc *v) {
  FuncState *fs = ls->fs;
  int extra = fs->freereg;
  int conflict = 0;
  for (; lh; lh = lh->prev) {
    if (lh->v.k == VINDEXED || lh->v.k == VINDEXUP) {
      if (lh->v.k == VINDEXED && v->k == VLOCAL && lh->v.u.ind.t == v->u.info) {
        conflict = 1;
        lh->v.u.ind.t = extra;
      }
      if (v->k == VLOCAL && lh->v.u.ind.idx == v->u.info && lh->v.u.ind.idx >= 0) {
        conflict = 1;
        lh->v.u.ind.idx = extra;
      }
      if (lh->v.k == VINDEXUP && v->k == VUPVAL && lh->v.u.ind.t == v->u.info) {
        /* upvalue table: no register conflict */
      }
    }
  }
  if (conflict) {
    emit(fs, OP_MOVE, extra, v->u.info, 0);
    reserveregs(fs, 1);
  }
}

static void adjust_assign(LexState *ls, int nvars, int nexps, expdesc *e) {
  FuncState *fs = ls->fs;
  int needed = nvars - nexps;
  if (e->k == VCALL || e->k == VVARARG) {
    int extra = needed + 1;
    if (extra < 0) extra = 0;
    setreturns(fs, e, extra);
    if (extra > 0) {
      if (e->k == VCALL) reserveregs(fs, extra - 1 + 1 - 1);
    }
    if (e->k == VCALL) {
      /* results start at the call's base register */
      fs->freereg = fs->f->code[e->u.info].a + extra;
      checkstack(fs, 0);
      if (fs->freereg > fs->f->maxstack) fs->f->maxstack = fs->freereg;
    }
  } else {
    if (e->k != VVOID) exp2nextreg(fs, e);
    if (needed > 0) {
      reserveregs(fs, needed);
      nil2reg(fs, fs->freereg - needed, needed);
    }
  }
  if (needed < 0) fs->freereg += needed;
}

static void restassign(LexState *ls, struct LHS_assign *lh, int nvars) {
  expdesc e;
  check_condition(ls, lh->v.k == VLOCAL || lh->v.k == VUPVAL ||
                      lh->v.k == VINDEXED || lh->v.k == VINDEXUP,
                  "syntax error");
  if (lh->v.k == VLOCAL) {
    Vardesc *vd = getlocalvardesc(ls->fs, lh->v.vidx);
    if (vd->kind == RDKCONST || vd->kind == RDKTOCLOSE)
      lex_syntaxerror(ls, strdata(lu_strfmt(ls->L,
          "attempt to assign to const variable '%s'", strdata(vd->name))));
  }
  if (lh->v.k == VUPVAL || lh->v.k == VINDEXED || lh->v.k == VINDEXUP ||
      lh->v.k == VLOCAL) { /* ok */ }
  if (testnext(ls, ',')) {
    struct LHS_assign nv;
    nv.prev = lh;
    { expdesc dummy; (void)dummy; }
    {
      /* suffixedexp */
      extern void lu_dummy(void);
    }
    {
      void suffixedexp(LexState *ls, expdesc *v);
      suffixedexp(ls, &nv.v);
      if (nv.v.k != VINDEXED && nv.v.k != VINDEXUP)
        check_conflict(ls, lh, &nv.v);
      restassign(ls, &nv, nvars + 1);
    }
  } else {
    int nexps;
    int explist(LexState *ls, expdesc *v);
    checknext(ls, '=');
    nexps = explist(ls, &e);
    if (nexps != nvars) adjust_assign(ls, nvars, nexps, &e);
    else {
      setoneret(ls->fs, &e);
      storevar(ls->fs, &lh->v, &e);
      return;
    }
  }
  init_exp(&e, VNONRELOC, ls->fs->freereg - 1);
  storevar(ls->fs, &lh->v, &e);
}

int explist(LexState *ls, expdesc *v) {
  int n = 1;
  expr(ls, v);
  while (testnext(ls, ',')) {
    exp2nextreg(ls->fs, v);
    expr(ls, v);
    n++;
  }
  return n;
}

static void funcargs(LexState *ls, expdesc *f) {
  FuncState *fs = ls->fs;
  expdesc args;
  int base, nparams;
  int line = ls->linenumber;
  uint8_t nk = f->nkind; Str *nn = f->nname;
  switch (ls->t.token) {
    case '(': {
      lex_next(ls);
      if (ls->t.token == ')') args.k = VVOID;
      else { explist(ls, &args); if (args.k == VCALL || args.k == VVARARG) setreturns(fs, &args, -1); }
      check_match(ls, ')', '(', line);
      break;
    }
    case '{': {
      void constructor(LexState *ls, expdesc *t);
      constructor(ls, &args);
      break;
    }
    case TK_STRING: {
      codestring(&args, ls->t.seminfo.ts);
      lex_next(ls);
      break;
    }
    default: lex_syntaxerror(ls, "function arguments expected"); return;
  }
  base = f->u.info;
  if (args.k == VCALL || args.k == VVARARG) nparams = -1;
  else {
    if (args.k != VVOID) exp2nextreg(fs, &args);
    nparams = fs->freereg - (base + 1);
  }
  init_exp(f, VCALL, emit(fs, OP_CALL, base, nparams + 1, 2));
  addhint_raw(fs, f->u.info, 0, nk, nn);
  fixline(fs, f->u.info, line);
  fs->freereg = base + 1;
}

static void primaryexp(LexState *ls, expdesc *v) {
  switch (ls->t.token) {
    case '(': {
      int line = ls->linenumber;
      lex_next(ls);
      expr(ls, v);
      check_match(ls, ')', '(', line);
      dischargevars(ls->fs, v);
      setoneret(ls->fs, v);
      if (v->k == VCALL) { /* already single */ }
      v->nkind = HN_NONE; v->nname = NULL;
      return;
    }
    case TK_NAME: singlevar(ls, v); return;
    default: lex_syntaxerror(ls, "unexpected symbol");
  }
}

void suffixedexp(LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  primaryexp(ls, v);
  for (;;) {
    switch (ls->t.token) {
      case '.': {
        expdesc key;
        lex_next(ls);
        { Str *n = str_checkname(ls); codestring(&key, n);
          indexed(fs, v, &key);
          v->nkind = HN_FIELD; v->nname = n; }
        break;
      }
      case '[': {
        expdesc key;
        exp2anyregup(fs, v);
        lex_next(ls);
        expr(ls, &key);
        exp2val(fs, &key);
        checknext(ls, ']');
        indexed(fs, v, &key);
        v->nkind = HN_NONE; v->nname = NULL;
        break;
      }
      case ':': {
        expdesc key;
        Str *n;
        int pc;
        lex_next(ls);
        n = str_checkname(ls);
        codestring(&key, n);
        /* self */
        {
          int base;
          exp2anyreg(fs, v);
          freeexp(fs, v);
          base = fs->freereg;
          reserveregs(fs, 2);
          pc = emit(fs, OP_SELF, base, v->u.info, exp2rk(fs, &key));
          addhint_raw(fs, pc, 1, v->nkind, v->nname);
          init_exp(v, VNONRELOC, base);
          v->nkind = HN_METHOD; v->nname = n;
        }
        funcargs(ls, v);
        break;
      }
      case '(': case TK_STRING: case '{': {
        exp2nextreg(fs, v);
        funcargs(ls, v);
        break;
      }
      default: (void)line; return;
    }
  }
}

/* table constructor */
struct ConsControl {
  expdesc v;
  expdesc *t;
  int nh, na, tostore;
};

static void closelistfield(FuncState *fs, struct ConsControl *cc) {
  if (cc->v.k == VVOID) return;
  exp2nextreg(fs, &cc->v);
  cc->v.k = VVOID;
  if (cc->tostore == 50) {
    emit(fs, OP_SETLIST, cc->t->u.info, cc->tostore, cc->na - cc->tostore);
    cc->na += 0;
    cc->tostore = 0;
    fs->freereg = cc->t->u.info + 1;
  }
}

static void lastlistfield(FuncState *fs, struct ConsControl *cc) {
  if (cc->tostore == 0) return;
  if (cc->v.k == VCALL || cc->v.k == VVARARG) {
    setreturns(fs, &cc->v, -1);
    emit(fs, OP_SETLIST, cc->t->u.info, 0, cc->na - cc->tostore);
  } else {
    if (cc->v.k != VVOID) exp2nextreg(fs, &cc->v);
    emit(fs, OP_SETLIST, cc->t->u.info, cc->tostore, cc->na - cc->tostore);
  }
  fs->freereg = cc->t->u.info + 1;
}

static void listfield(LexState *ls, struct ConsControl *cc) {
  expr(ls, &cc->v);
  cc->na++;
  cc->tostore++;
}

static void recfield(LexState *ls, struct ConsControl *cc) {
  FuncState *fs = ls->fs;
  int reg = ls->fs->freereg;
  expdesc tab, key, val;
  if (ls->t.token == TK_NAME) codestring(&key, str_checkname(ls));
  else { lex_next(ls); expr(ls, &key); checknext(ls, ']'); }
  cc->nh++;
  checknext(ls, '=');
  tab = *cc->t;
  indexed(fs, &tab, &key);
  expr(ls, &val);
  storevar(fs, &tab, &val);
  fs->freereg = reg;
}

static void field(LexState *ls, struct ConsControl *cc) {
  switch (ls->t.token) {
    case TK_NAME: {
      if (lex_lookahead(ls) != '=') listfield(ls, cc);
      else recfield(ls, cc);
      break;
    }
    case '[': recfield(ls, cc); break;
    default: listfield(ls, cc); break;
  }
}

void constructor(LexState *ls, expdesc *t) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  int pc = emit(fs, OP_NEWTAB, 0, 0, 0);
  struct ConsControl cc;
  cc.na = cc.nh = cc.tostore = 0;
  cc.t = t;
  init_exp(t, VNONRELOC, fs->freereg);
  reserveregs(fs, 1);
  init_exp(&cc.v, VVOID, 0);
  fs->f->code[pc].a = (uint8_t)t->u.info;
  checknext(ls, '{');
  do {
    if (ls->t.token == '}') break;
    closelistfield(fs, &cc);
    field(ls, &cc);
  } while (testnext(ls, ',') || testnext(ls, ';'));
  check_match(ls, '}', '{', line);
  lastlistfield(fs, &cc);
  fs->f->code[pc].b = cc.na;
  fs->f->code[pc].c = cc.nh;
}

static void setvararg(FuncState *fs, int nparams) {
  fs->f->is_vararg = 1;
  (void)nparams;
}

static void parlist(LexState *ls) {
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  int nparams = 0;
  int isvararg = 0;
  if (ls->t.token != ')') {
    do {
      switch (ls->t.token) {
        case TK_NAME: new_localvar(ls, str_checkname(ls)); nparams++; break;
        case TK_DOTS: lex_next(ls); isvararg = 1; break;
        default: lex_syntaxerror(ls, "<name> expected");
      }
    } while (!isvararg && testnext(ls, ','));
  }
  adjustlocalvars(ls, nparams);
  f->numparams = fs->nactvar;
  if (isvararg) setvararg(fs, f->numparams);
  reserveregs(fs, fs->nactvar);
}

static void body(LexState *ls, expdesc *e, int ismethod, int line) {
  FuncState new_fs;
  BlockCnt bl;
  Proto *f = lu_newproto(ls->L);
  FuncState *host = ls->fs;
  Proto *hf = host->f;
  hf->p = (Proto **)lu_growvec(ls->L, hf->p, &host->pcap, hf->np + 1, sizeof(Proto *));
  hf->p[hf->np++] = f;
  new_fs.f = f;
  f->linedefined = line;
  open_func(ls, &new_fs, &bl);
  checknext(ls, '(');
  if (ismethod) { new_localvar(ls, lu_newstr(ls->L, "self")); adjustlocalvars(ls, 1); reserveregs(ls->fs, 1); }
  parlist(ls);
  checknext(ls, ')');
  statlist(ls);
  f->lastlinedefined = ls->linenumber;
  check_match(ls, TK_END, TK_FUNCTION, line);
  close_func(ls);
  init_exp(e, VRELOC, emit(host, OP_CLOSURE, 0, hf->np - 1, 0));
  exp2nextreg(host, e);
}

/* -------------------------------------------------------------- operators */

typedef enum BinOpr {
  OPR_ADD, OPR_SUB, OPR_MUL, OPR_MOD, OPR_POW, OPR_DIV, OPR_IDIV,
  OPR_BAND, OPR_BOR, OPR_BXOR, OPR_SHL, OPR_SHR,
  OPR_CONCAT,
  OPR_EQ, OPR_LT, OPR_LE, OPR_NE, OPR_GT, OPR_GE,
  OPR_AND, OPR_OR,
  OPR_NOBINOPR
} BinOpr;

typedef enum UnOpr { OPR_MINUS, OPR_BNOT, OPR_NOT, OPR_LEN, OPR_NOUNOPR } UnOpr;

static const struct { uint8_t left, right; } priority[] = {
  {10,10},{10,10},{11,11},{11,11},{14,13},{11,11},{11,11},
  {6,6},{4,4},{5,5},{7,7},{7,7},
  {9,8},
  {3,3},{3,3},{3,3},{3,3},{3,3},{3,3},
  {2,2},{1,1}
};
#define UNARY_PRIORITY  12

static BinOpr getbinopr(int op) {
  switch (op) {
    case '+': return OPR_ADD;
    case '-': return OPR_SUB;
    case '*': return OPR_MUL;
    case '%': return OPR_MOD;
    case '^': return OPR_POW;
    case '/': return OPR_DIV;
    case TK_IDIV: return OPR_IDIV;
    case '&': return OPR_BAND;
    case '|': return OPR_BOR;
    case '~': return OPR_BXOR;
    case TK_SHL: return OPR_SHL;
    case TK_SHR: return OPR_SHR;
    case TK_CONCAT: return OPR_CONCAT;
    case TK_NE: return OPR_NE;
    case TK_EQ: return OPR_EQ;
    case '<': return OPR_LT;
    case TK_LE: return OPR_LE;
    case '>': return OPR_GT;
    case TK_GE: return OPR_GE;
    case TK_AND: return OPR_AND;
    case TK_OR: return OPR_OR;
    default: return OPR_NOBINOPR;
  }
}

static UnOpr getunopr(int op) {
  switch (op) {
    case TK_NOT: return OPR_NOT;
    case '-': return OPR_MINUS;
    case '~': return OPR_BNOT;
    case '#': return OPR_LEN;
    default: return OPR_NOUNOPR;
  }
}

static void prefix(FuncState *fs, UnOpr op, expdesc *e, int line) {
  static expdesc ef;
  init_exp(&ef, VKINT, 0);
  ef.u.ival = 0;
  switch (op) {
    case OPR_MINUS:
      if (constfolding(fs, AR_UNM, e, e)) break;
      codeunary(fs, OP_UNM, e, line); break;
    case OPR_BNOT:
      if (constfolding(fs, AR_BNOT, e, e)) break;
      codeunary(fs, OP_BNOT, e, line); break;
    case OPR_LEN: codeunary(fs, OP_LEN, e, line); break;
    case OPR_NOT: codenot(fs, e); break;
    default: break;
  }
}

static void infix(FuncState *fs, BinOpr op, expdesc *v) {
  switch (op) {
    case OPR_AND: goiftrue(fs, v); break;
    case OPR_OR: goiffalse(fs, v); break;
    case OPR_CONCAT: exp2nextreg(fs, v); break;
    case OPR_ADD: case OPR_SUB: case OPR_MUL: case OPR_DIV: case OPR_IDIV:
    case OPR_MOD: case OPR_POW:
    case OPR_BAND: case OPR_BOR: case OPR_BXOR: case OPR_SHL: case OPR_SHR: {
      if (!tonumeral(v, NULL)) exp2rk(fs, v);
      break;
    }
    default: exp2rk(fs, v); break;
  }
}

static void posfix(FuncState *fs, BinOpr op, expdesc *e1, expdesc *e2, int line) {
  switch (op) {
    case OPR_AND: {
      dischargevars(fs, e2);
      concatjump(fs, &e2->f, e1->f);
      *e1 = *e2;
      break;
    }
    case OPR_OR: {
      dischargevars(fs, e2);
      concatjump(fs, &e2->t, e1->t);
      *e1 = *e2;
      break;
    }
    case OPR_CONCAT: {
      exp2val(fs, e2);
      /* e1 is in a register (from infix); e2 goes to the next register */
      exp2nextreg(fs, e2);
      {
        int b = e1->u.info, c = e2->u.info;
        uint8_t k1 = e1->nkind, k2 = e2->nkind;
        Str *n1 = e1->nname, *n2 = e2->nname;
        int pc;
        /* fold with a previous CONCAT that ends right before b.. */
        if (fs->pc > 0 && fs->f->code[fs->pc - 1].op == OP_CONCAT &&
            fs->f->code[fs->pc - 1].c == b && fs->pc - 1 > fs->lasttarget) {
          Instr *prev = &fs->f->code[fs->pc - 1];
          prev->c = c;
          fs->freereg = prev->b + 1;
          e1->k = VRELOC;
          e1->u.info = fs->pc - 1;
          e1->nkind = HN_NONE; e1->nname = NULL;
          if (k2 != HN_NONE) addhint_raw(fs, fs->pc - 1, 3 + (c - prev->b), k2, n2);
          break;
        }
        fs->freereg = b;
        pc = emit(fs, OP_CONCAT, 0, b, c);
        e1->k = VRELOC;
        e1->u.info = pc;
        e1->nkind = HN_NONE; e1->nname = NULL;
        if (k1 != HN_NONE) addhint_raw(fs, pc, 3 + 0, k1, n1);
        if (k2 != HN_NONE) addhint_raw(fs, pc, 3 + (c - b), k2, n2);
        fixline(fs, pc, line);
      }
      break;
    }
    case OPR_ADD: case OPR_SUB: case OPR_MUL: case OPR_DIV: case OPR_IDIV:
    case OPR_MOD: case OPR_POW:
    case OPR_BAND: case OPR_BOR: case OPR_BXOR: case OPR_SHL: case OPR_SHR: {
      if (constfolding(fs, (int)op, e1, e2)) break;
      codearith(fs, (int)op, e1, e2, line);
      break;
    }
    case OPR_EQ: codecomp(fs, 0, e1, e2); break;
    case OPR_NE: codecomp(fs, 1, e1, e2); break;
    case OPR_LT: codecomp(fs, 2, e1, e2); break;
    case OPR_LE: codecomp(fs, 3, e1, e2); break;
    case OPR_GT: codecomp(fs, 4, e1, e2); break;
    case OPR_GE: codecomp(fs, 5, e1, e2); break;
    default: break;
  }
}

static void simpleexp(LexState *ls, expdesc *v) {
  switch (ls->t.token) {
    case TK_FLT: init_exp(v, VKFLT, 0); v->u.nval = ls->t.seminfo.r; break;
    case TK_INT: init_exp(v, VKINT, 0); v->u.ival = ls->t.seminfo.i; break;
    case TK_STRING: codestring(v, ls->t.seminfo.ts); break;
    case TK_NIL: init_exp(v, VNIL, 0); break;
    case TK_TRUE: init_exp(v, VTRUE, 0); break;
    case TK_FALSE: init_exp(v, VFALSE, 0); break;
    case TK_DOTS: {
      FuncState *fs = ls->fs;
      check_condition(ls, fs->f->is_vararg, "cannot use '...' outside a vararg function");
      init_exp(v, VVARARG, emit(fs, OP_VARARG, 0, 1, 0));
      break;
    }
    case '{': constructor(ls, v); return;
    case TK_FUNCTION: lex_next(ls); body(ls, v, 0, ls->linenumber); return;
    default: suffixedexp(ls, v); return;
  }
  lex_next(ls);
}

static BinOpr subexpr(LexState *ls, expdesc *v, int limit) {
  BinOpr op;
  UnOpr uop = getunopr(ls->t.token);
  if (uop != OPR_NOUNOPR) {
    int line = ls->linenumber;
    lex_next(ls);
    subexpr(ls, v, UNARY_PRIORITY);
    prefix(ls->fs, uop, v, line);
  } else simpleexp(ls, v);
  op = getbinopr(ls->t.token);
  while (op != OPR_NOBINOPR && priority[op].left > limit) {
    expdesc v2;
    BinOpr nextop;
    int line = ls->linenumber;
    lex_next(ls);
    infix(ls->fs, op, v);
    nextop = subexpr(ls, &v2, priority[op].right);
    posfix(ls->fs, op, v, &v2, line);
    op = nextop;
  }
  return op;
}

static void expr(LexState *ls, expdesc *v) { subexpr(ls, v, 0); }

/* ------------------------------------------------------------- statements */

static int cond(LexState *ls) {
  expdesc v;
  expr(ls, &v);
  if (v.k == VNIL) v.k = VFALSE;
  goiftrue(ls->fs, &v);
  return v.f;
}

static void gotostat(LexState *ls, int line, Str *name) {
  FuncState *fs = ls->fs;
  Labeldesc *lb = findlabel(ls, name);
  if (lb) {
    int lvl = reglevel(fs, lb->nactvar);
    int j;
    if (luaY_nvarstack(fs) > lvl) {
      /* leaving scopes: close */
      j = emit(fs, OP_JMP, lvl + 1, NO_JUMP, 0);
    } else j = jump(fs);
    patchlist(fs, j, lb->pc);
  } else {
    int j = jump(fs);
    newlabelentry(ls, 1, name, line, j);
  }
}

static void breakstat(LexState *ls, int line) {
  gotostat(ls, line, lu_newstr(ls->L, "break"));
}

static void checkrepeated(LexState *ls, Str *name) {
  if (findlabel(ls, name) != NULL)
    lex_syntaxerror(ls, strdata(lu_strfmt(ls->L,
        "label '%s' already defined", strdata(name))));
}

static void labelstat(LexState *ls, Str *name, int line) {
  checknext(ls, TK_DBCOLON);
  while (ls->t.token == ';' || ls->t.token == TK_DBCOLON) statement(ls);
  checkrepeated(ls, name);
  createlabel(ls, name, line, block_follow(ls, 0));
}

static void whilestat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int whileinit, condexit;
  BlockCnt bl;
  lex_next(ls);
  whileinit = getlabel(fs);
  condexit = cond(ls);
  enterblock(fs, &bl, 1);
  checknext(ls, TK_DO);
  block(ls);
  { int j = jump(fs); patchlist(fs, j, whileinit); }
  check_match(ls, TK_END, TK_WHILE, line);
  leaveblock(fs);
  patchtohere(fs, condexit);
}

static void repeatstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int condexit;
  int repeat_init = getlabel(fs);
  BlockCnt bl1, bl2;
  enterblock(fs, &bl1, 1);
  enterblock(fs, &bl2, 0);
  lex_next(ls);
  statlist(ls);
  check_match(ls, TK_UNTIL, TK_REPEAT, line);
  condexit = cond(ls);
  leaveblock(fs);
  if (bl2.upval) {
    int exit_ = jump(fs);
    patchtohere(fs, condexit);
    emit(fs, OP_CLOSE, reglevel(fs, bl2.nactvar), 0, 0);
    condexit = jump(fs);
    patchtohere(fs, exit_);
  }
  patchlist(fs, condexit, repeat_init);
  leaveblock(fs);
}

static void exp1(LexState *ls) {
  expdesc e;
  expr(ls, &e);
  exp2nextreg(ls->fs, &e);
}

static void forbody(LexState *ls, int base, int line, int nvars, int isgen) {
  BlockCnt bl;
  FuncState *fs = ls->fs;
  int prep, endfor;
  checknext(ls, TK_DO);
  prep = isgen ? emit(fs, OP_TFORPREP, base, NO_JUMP, 0)
               : emit(fs, OP_FORPREP, base, NO_JUMP, 0);
  enterblock(fs, &bl, 0);
  adjustlocalvars(ls, nvars);
  reserveregs(fs, nvars);
  block(ls);
  leaveblock(fs);
  fixjump(fs, prep, fs->pc);
  if (isgen) {
    emit(fs, OP_TFORCALL, base, 0, nvars);
    fixline(fs, fs->pc - 1, line);
  }
  endfor = isgen ? emit(fs, OP_TFORLOOP, base + 2, NO_JUMP, 0)
                 : emit(fs, OP_FORLOOP, base, NO_JUMP, 0);
  fixjump(fs, endfor, prep + 1);
  fixline(fs, endfor, line);
}

static void fornum(LexState *ls, Str *varname, int line) {
  FuncState *fs = ls->fs;
  int base = fs->freereg;
  new_localvar(ls, lu_newstr(ls->L, "(for state)"));
  new_localvar(ls, lu_newstr(ls->L, "(for state)"));
  new_localvar(ls, lu_newstr(ls->L, "(for state)"));
  new_localvar(ls, varname);
  checknext(ls, '=');
  exp1(ls);
  checknext(ls, ',');
  exp1(ls);
  if (testnext(ls, ',')) exp1(ls);
  else { emit(fs, OP_LOADINT, fs->freereg, 1, 0); reserveregs(fs, 1); }
  adjustlocalvars(ls, 3);
  forbody(ls, base, line, 1, 0);
}

static void forlist(LexState *ls, Str *indexname) {
  FuncState *fs = ls->fs;
  expdesc e;
  int nvars = 5;
  int line;
  int base = fs->freereg;
  new_localvar(ls, lu_newstr(ls->L, "(for state)"));
  new_localvar(ls, lu_newstr(ls->L, "(for state)"));
  new_localvar(ls, lu_newstr(ls->L, "(for state)"));
  new_localvar(ls, lu_newstr(ls->L, "(for state)"));
  new_localvar(ls, indexname);
  while (testnext(ls, ',')) { new_localvar(ls, str_checkname(ls)); nvars++; }
  checknext(ls, TK_IN);
  line = ls->linenumber;
  adjust_assign(ls, 4, explist(ls, &e), &e);
  adjustlocalvars(ls, 4);
  /* the 4th value is a to-be-closed variable */
  emit(fs, OP_TBC, base + 3, 0, 0);
  checkstack(fs, 3);
  forbody(ls, base, line, nvars - 4, 1);
}

static void forstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  Str *varname;
  BlockCnt bl;
  enterblock(fs, &bl, 1);
  lex_next(ls);
  varname = str_checkname(ls);
  switch (ls->t.token) {
    case '=': fornum(ls, varname, line); break;
    case ',': case TK_IN: forlist(ls, varname); break;
    default: lex_syntaxerror(ls, "'=' or 'in' expected");
  }
  check_match(ls, TK_END, TK_FOR, line);
  leaveblock(fs);
}

static void test_then_block(LexState *ls, int *escapelist) {
  BlockCnt bl;
  FuncState *fs = ls->fs;
  expdesc v;
  int jf;
  lex_next(ls);
  expr(ls, &v);
  checknext(ls, TK_THEN);
  if (ls->t.token == TK_BREAK) {
    int line = ls->linenumber;
    goiffalse(ls->fs, &v);
    lex_next(ls);
    enterblock(fs, &bl, 0);
    breakstat(ls, line);
    while (testnext(ls, ';')) ;
    if (block_follow(ls, 0)) { leaveblock(fs); return; }
    else jf = jump(fs);
  } else {
    goiftrue(ls->fs, &v);
    enterblock(fs, &bl, 0);
    jf = v.f;
  }
  statlist(ls);
  leaveblock(fs);
  if (ls->t.token == TK_ELSE || ls->t.token == TK_ELSEIF) {
    int j = jump(fs);
    concatjump(fs, escapelist, j);
  }
  patchtohere(fs, jf);
}

static void ifstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int escapelist = NO_JUMP;
  test_then_block(ls, &escapelist);
  while (ls->t.token == TK_ELSEIF) test_then_block(ls, &escapelist);
  if (testnext(ls, TK_ELSE)) block(ls);
  check_match(ls, TK_END, TK_IF, line);
  patchtohere(fs, escapelist);
}

static void localfunc(LexState *ls) {
  expdesc b;
  FuncState *fs = ls->fs;
  int fvar = fs->nactvar;
  new_localvar(ls, str_checkname(ls));
  adjustlocalvars(ls, 1);
  reserveregs(fs, 1);
  body(ls, &b, 0, ls->linenumber);
  /* the closure was placed at the variable's register by exp2nextreg */
  {
    Vardesc *vd = getlocalvardesc(fs, fvar);
    LocVar *lv = localdebuginfo(fs, fvar);
    if (b.k == VNONRELOC && b.u.info != vd->ridx)
      emit(fs, OP_MOVE, vd->ridx, b.u.info, 0);
    fs->freereg = vd->ridx + 1;
    if (lv) lv->startpc = fs->pc;
  }
}

static int getlocalattribute(LexState *ls) {
  if (testnext(ls, '<')) {
    Str *ts = str_checkname(ls);
    const char *attr = strdata(ts);
    checknext(ls, '>');
    if (strcmp(attr, "const") == 0) return RDKCONST;
    else if (strcmp(attr, "close") == 0) return RDKTOCLOSE;
    else lex_syntaxerror(ls, strdata(lu_strfmt(ls->L,
        "unknown attribute '%s'", attr)));
  }
  return VDKREG;
}

static void checktoclose(FuncState *fs, int level) {
  if (level != -1) {
    fs->bl->insidetbc = 1;
    fs->needclose = 1;
    emit(fs, OP_TBC, reglevel(fs, level), 0, 0);
  }
}

static void localstat(LexState *ls) {
  FuncState *fs = ls->fs;
  int toclose = -1;
  Vardesc *var;
  int vidx, kind;
  int nvars = 0, nexps;
  expdesc e;
  do {
    vidx = new_localvar(ls, str_checkname(ls));
    kind = getlocalattribute(ls);
    getlocalvardesc(fs, vidx)->kind = (uint8_t)kind;
    if (kind == RDKTOCLOSE) {
      if (toclose != -1)
        lex_syntaxerror(ls, "multiple to-be-closed variables in local list");
      toclose = fs->nactvar + nvars;
    }
    nvars++;
  } while (testnext(ls, ','));
  if (testnext(ls, '=')) nexps = explist(ls, &e);
  else { e.k = VVOID; nexps = 0; }
  var = getlocalvardesc(fs, vidx);
  if (nvars == nexps && var->kind == RDKCONST &&
      (e.k == VKINT || e.k == VKFLT || e.k == VKSTR || e.k == VNIL ||
       e.k == VTRUE || e.k == VFALSE) && e.t == NO_JUMP && e.f == NO_JUMP) {
    var->kind = RDKCTC;
    switch (e.k) {
      case VKINT: var->k = mkint(e.u.ival); break;
      case VKFLT: var->k = mkflt(e.u.nval); break;
      case VKSTR: var->k = mkgc(T_STR, e.u.strval); break;
      case VNIL: var->k = mknil(); break;
      case VTRUE: var->k = mkbool(1); break;
      default: var->k = mkbool(0); break;
    }
    adjustlocalvars(ls, nvars - 1);
    fs->nactvar++;
  } else {
    adjust_assign(ls, nvars, nexps, &e);
    adjustlocalvars(ls, nvars);
  }
  checktoclose(fs, toclose);
}

static int funcname(LexState *ls, expdesc *v, Str **name) {
  int ismethod = 0;
  singlevar(ls, v);
  *name = v->nname;
  while (ls->t.token == '.') {
    expdesc key;
    lex_next(ls);
    { Str *n = str_checkname(ls); codestring(&key, n); *name = n;
      indexed(ls->fs, v, &key); v->nkind = HN_FIELD; v->nname = n; }
  }
  if (ls->t.token == ':') {
    expdesc key;
    ismethod = 1;
    lex_next(ls);
    { Str *n = str_checkname(ls); codestring(&key, n); *name = n;
      indexed(ls->fs, v, &key); v->nkind = HN_METHOD; v->nname = n; }
  }
  return ismethod;
}

static void funcstat(LexState *ls, int line) {
  int ismethod;
  expdesc v, b;
  Str *name = NULL;
  lex_next(ls);
  ismethod = funcname(ls, &v, &name);
  body(ls, &b, ismethod, line);
  storevar(ls->fs, &v, &b);
  fixline(ls->fs, ls->fs->pc - 1, line);
}

static void exprstat(LexState *ls) {
  FuncState *fs = ls->fs;
  struct LHS_assign v;
  suffixedexp(ls, &v.v);
  if (ls->t.token == '=' || ls->t.token == ',') {
    v.prev = NULL;
    restassign(ls, &v, 1);
  } else {
    if (v.v.k != VCALL) lex_syntaxerror(ls, "syntax error");
    fs->f->code[v.v.u.info].c = 1;
  }
}

static void retstat(LexState *ls) {
  FuncState *fs = ls->fs;
  expdesc e;
  int nret;
  int first = luaY_nvarstack(fs);
  if (block_follow(ls, 1) || ls->t.token == ';') nret = 0;
  else {
    nret = explist(ls, &e);
    if (e.k == VCALL || e.k == VVARARG) {
      setreturns(fs, &e, -1);
      if (e.k == VCALL && nret == 1 && !fs->bl->insidetbc && !fs->needclose) {
        fs->f->code[e.u.info].op = OP_TAILCALL;
      }
      nret = -1;
    } else {
      if (nret == 1) first = exp2anyreg(fs, &e);
      else { exp2nextreg(fs, &e); first = luaY_nvarstack(fs); }
    }
  }
  emit(fs, OP_RETURN, first, nret + 1, 0);
  testnext(ls, ';');
}

static void statement(LexState *ls) {
  int line = ls->linenumber;
  switch (ls->t.token) {
    case ';': lex_next(ls); break;
    case TK_IF: ifstat(ls, line); break;
    case TK_WHILE: whilestat(ls, line); break;
    case TK_DO: { lex_next(ls); block(ls); check_match(ls, TK_END, TK_DO, line); break; }
    case TK_FOR: forstat(ls, line); break;
    case TK_REPEAT: repeatstat(ls, line); break;
    case TK_FUNCTION: funcstat(ls, line); break;
    case TK_LOCAL: {
      lex_next(ls);
      if (testnext(ls, TK_FUNCTION)) localfunc(ls);
      else localstat(ls);
      break;
    }
    case TK_DBCOLON: { lex_next(ls); labelstat(ls, str_checkname(ls), line); break; }
    case TK_RETURN: { lex_next(ls); retstat(ls); break; }
    case TK_BREAK: { lex_next(ls); breakstat(ls, line); break; }
    case TK_GOTO: { lex_next(ls); gotostat(ls, line, str_checkname(ls)); break; }
    default: exprstat(ls); break;
  }
  ls->fs->freereg = luaY_nvarstack(ls->fs);
}

static void statlist(LexState *ls) {
  while (!block_follow(ls, 1)) {
    if (ls->t.token == TK_RETURN) { statement(ls); return; }
    statement(ls);
  }
}

static void mainfunc(LexState *ls, FuncState *fs) {
  BlockCnt bl;
  expdesc v;
  UpvalDesc *env;
  open_func(ls, fs, &bl);
  fs->f->is_vararg = 1;
  init_exp(&v, VLOCAL, 0);
  env = allocupvalue(fs);
  env->instack = 1; env->idx = 0; env->name = lu_newstr(ls->L, "_ENV");
  lex_next(ls);
  statlist(ls);
  check(ls, TK_EOS);
  close_func(ls);
}

Proto *lu_parse(lua_State *L, const char *buf, size_t len, const char *chunkname) {
  LexState ls;
  FuncState fs;
  Dyndata dyd;
  Proto *f = lu_newproto(L);
  Str *src = lu_newstr(L, chunkname);
  memset(&dyd, 0, sizeof(dyd));
  fs.f = f;
  f->linedefined = 0;
  f->lastlinedefined = 0;
  lex_setinput(L, &ls, buf, len, src);
  ls.dyd = &dyd;
  L->G->fixed[L->G->nfixed++] = mkgc(T_PROTO, f);
  mainfunc(&ls, &fs);
  L->G->nfixed--;
  lu_free(L, dyd.actvar, (size_t)dyd.cactvar * sizeof(Vardesc));
  lu_free(L, dyd.gt, (size_t)dyd.cgt * sizeof(Labeldesc));
  lu_free(L, dyd.label, (size_t)dyd.clabel * sizeof(Labeldesc));
  buf_free(&ls.buff);
  return f;
}

