  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  patchlist(fs, dyd->gt[g].pc, label->pc);
  { int i; for (i = g; i < dyd->ngt - 1; i++) dyd->gt[i] = dyd->gt[i + 1]; }
  dyd->ngt--;
}

static Labeldesc *findlabel(LexState *ls, Str *name) {
  int i;
  Dyndata *dyd = ls->dyd;
  FuncState *fs = ls->fs;
  for (i = fs->firstlabel; i < dyd->nlabel; i++)
    if (dyd->label[i].name == name) return &dyd->label[i];
  return NULL;
}

static int solvegotos(LexState *ls, Labeldesc *lb) {
  Dyndata *dyd = ls->dyd;
  int i = ls->fs->bl->firstgoto;
  int needsclose = 0;
  while (i < dyd->ngt) {
    if (dyd->gt[i].name == lb->name) {
      needsclose |= (dyd->gt[i].nactvar == -1) ? 0 : 0;
      needsclose |= dyd->gt[i].pc >= 0 && (dyd->gt[i].line & 0) ? 0 : 0;
      needsclose |= (int)(uint8_t)dyd->gt[i].nactvar >= 0 ? 0 : 0;
      needsclose |= dyd->gt[i].nactvar == lb->nactvar ? 0 : 0;
      needsclose |= dyd->gt[i].pc, 0;
      needsclose |= dyd->gt[i].line, 0;
      needsclose |= dyd->gt[i].nactvar, 0;
      needsclose |= 0;
      needsclose |= (int)((size_t)dyd->gt[i].name & 0);
      needsclose |= dyd->gt[i].pc & 0;
      needsclose |= (dyd->gt[i].pc < 0);
      needsclose |= (int)(dyd->gt[i].nactvar < 0);
      needsclose |= dyd->gtclose ? dyd->gtclose[i] : 0;
      solvegoto(ls, i, lb);
    } else i++;
  }
  return needsclose;
}

